/* KHBD Âm nhạc Lớp 1 KNTT — Bút Xanh, tích hợp NLS + AI */
window.KHO_DATA_L1_AMNHAC = [
{"lop":1,"mon":"Âm nhạc","tuan":1,"tiet":1,"bai":"Chủ đề 1: Âm thanh kì diệu — Học hát: Vào rừng hoa (Việt Anh)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng theo giai điệu bài hát Vào rừng hoa.\n- Bước đầu cảm nhận tính chất vui tươi, trong sáng của bài hát.\n- Biết hát kết hợp vỗ tay theo phách đơn giản.\n2. Năng lực chung\n- Tự chủ và tự học: mạnh dạn hát trước lớp, tự tập lại lời ca.\n- Giao tiếp và hợp tác: biết hát hòa giọng cùng các bạn.\n3. Phẩm chất\n- Yêu thiên nhiên, yêu cảnh đẹp quê hương.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát cùng tên tác giả.","dodung":"- Giáo viên: đàn Organ (hoặc file nhạc đệm), loa, tranh cảnh rừng hoa, thanh phách, thiết bị trình chiếu/loa mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách (hoặc nhạc cụ gõ tự tạo).","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem tranh cảnh rừng hoa nhiều màu sắc và hỏi: Các em thấy gì trong tranh? Có thích đi chơi trong rừng hoa không?\n- GV bắt nhịp cho cả lớp vận động nhẹ nhàng, dẫn vào bài hát.","hs":"- HS quan sát, trả lời: có hoa, có cây, có bướm...\n- HS vận động, lắng nghe."},{"ten":"2. Khám phá — Nghe và học hát","gv":"- GV mở bản hát mẫu (băng đĩa/học liệu số) cho HS nghe 1-2 lần.\n- GV đọc lời ca theo từng câu, chia bài thành các câu ngắn.\n- GV đàn giai điệu, hát mẫu và bắt nhịp cho HS hát từng câu nối tiếp đến hết bài.","hs":"- HS lắng nghe, nêu cảm nhận ban đầu.\n- HS đọc lời ca theo GV.\n- HS tập hát từng câu, hát nối các câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài theo nhạc đệm, sửa những chỗ hát chưa đúng.\n- GV hướng dẫn hát kết hợp vỗ tay theo phách.","hs":"- HS hát cả bài, hát theo dãy, tổ.\n- HS hát kết hợp vỗ tay theo phách."},{"ten":"4. Vận dụng","gv":"- GV mời vài HS/nhóm hát trước lớp.\n- GV dặn HS về hát cho ông bà, bố mẹ nghe.","hs":"- HS xung phong biểu diễn.\n- HS ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản hát mẫu bài “Vào rừng hoa” từ học liệu số, chiếu màn hình có tên bài hát và tên tác giả Việt Anh để HS đọc theo; GV mở từng câu ngắn, dừng cho HS nghe rồi hát nối tiếp, câu nào hát chưa đúng thì mở lại câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại ghi âm phần cả lớp hát kết hợp vỗ tay theo phách, rồi mở lại qua loa ngay tại lớp; HS nghe giọng hát của chính mình, chỉ ra chỗ hát chưa rõ lời hay vỗ tay chưa đều phách; GV thao tác thiết bị, HS chỉ nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Vào rừng hoa” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản hát mẫu, nói được tên bài hát “Vào rừng hoa” và tên tác giả Việt Anh, hát đúng lời theo từng câu.\n- HS nghe lại bản ghi âm của lớp, chỉ ra một chỗ hát chưa rõ lời hoặc vỗ tay chưa đúng phách rồi hát lại."}]},
{"lop":1,"mon":"Âm nhạc","tuan":2,"tiet":2,"bai":"Chủ đề 1: Âm thanh kì diệu — Ôn bài hát Vào rừng hoa; Đọc nhạc: Đô — Rê — Mi","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu bài Vào rừng hoa, kết hợp vỗ tay theo phách.\n- Bước đầu làm quen với ba nốt Đô — Rê — Mi qua kí hiệu bàn tay.\n- Đọc được cao độ ba nốt theo mẫu đơn giản.\n2. Năng lực chung\n- Tự chủ và tự học: tự luyện đọc nốt theo kí hiệu.\n3. Phẩm chất\n- Chăm chỉ luyện tập.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS đọc đúng cao độ “Đô — Rê — Mi” nhờ nghe mẫu từ đàn phím.","dodung":"- Giáo viên: đàn Organ/file nhạc, loa, tranh kí hiệu bàn tay Đô-Rê-Mi, thanh phách, thiết bị mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát lại bài Vào rừng hoa để tạo không khí.","hs":"- HS hát tập thể."},{"ten":"2. Khám phá — Làm quen Đô, Rê, Mi","gv":"- GV giới thiệu ba nốt Đô — Rê — Mi qua kí hiệu bàn tay; đọc mẫu cao độ từng nốt.\n- GV hướng dẫn HS đọc theo, kết hợp làm kí hiệu bàn tay.","hs":"- HS quan sát, nghe và đọc theo cao độ.\n- HS làm kí hiệu bàn tay theo GV."},{"ten":"3. Luyện tập","gv":"- GV cho HS đọc các mẫu âm ngắn với ba nốt; ôn hát bài hát kết hợp vỗ tay theo phách.","hs":"- HS đọc mẫu âm, ôn hát và vỗ tay theo phách."},{"ten":"4. Vận dụng","gv":"- GV cho nhóm/cá nhân đọc lại mẫu âm và làm kí hiệu bàn tay; nhận xét, tuyên dương.","hs":"- HS đọc và làm kí hiệu, nhận xét lẫn nhau."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở trên máy tính âm thanh chuẩn của ba nốt Đô — Rê — Mi kèm hình kí hiệu bàn tay từng nốt trên màn hình; bấm từng nốt cho HS nghe và làm kí hiệu theo, mở lại nốt HS còn đọc chênh; ôn bài “Vào rừng hoa” theo nhạc đệm sẵn có.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở bài tập tương tác nghe nốt trên máy chiếu: máy phát một trong ba nốt Đô, Rê, Mi, HS giơ kí hiệu bàn tay tương ứng, GV bấm hiện đáp án để cả lớp kiểm tra ngay; nốt nào nhiều bạn nhầm thì GV phát lại và cho đọc lại cùng nhạc đệm.\n⚠ (Miền 4: An toàn) GV thao tác đàn và máy tính, HS chỉ nghe và đọc theo, không tự bấm vào thiết bị của GV; mở âm lượng vừa đủ nghe để không hại tai; chỉ dùng phần mềm GV đã cài sẵn, không mở phần mềm hay trang khác trong giờ học.","hs":"- HS nghe mẫu cao độ, đọc đúng ba nốt Đô — Rê — Mi kết hợp làm kí hiệu bàn tay; hát bài “Vào rừng hoa” theo nhạc đệm.\n- HS nghe nốt máy phát, giơ đúng kí hiệu bàn tay, nhận ra nốt mình đọc còn chênh và đọc lại cho đúng."}]},
{"lop":1,"mon":"Âm nhạc","tuan":3,"tiet":3,"bai":"Chủ đề 1: Âm thanh kì diệu — Thường thức âm nhạc: Âm thanh tự nhiên và âm thanh của nhạc cụ (sáo trúc)","yccd":"1. Năng lực âm nhạc\n- Phân biệt bước đầu âm thanh tự nhiên và âm thanh của nhạc cụ.\n- Nhận biết và gọi tên nhạc cụ sáo trúc; cảm nhận âm sắc của sáo.\n2. Năng lực chung\n- Tự chủ: mạnh dạn nêu cảm nhận về âm thanh.\n3. Phẩm chất\n- Yêu thiên nhiên, yêu âm nhạc.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nêu được đặc điểm nổi bật của “Âm thanh tự nhiên và âm thanh của nhạc cụ (sáo trúc)” nhờ quan sát tư liệu số và nghe bản thu.","dodung":"- Giáo viên: loa, file âm thanh tự nhiên (tiếng suối, chim, gió), sáo trúc (hoặc hình ảnh/âm thanh sáo), tranh nhạc cụ, thiết bị số.\n- Học sinh: SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi Lắng nghe và đoán: đoán các âm thanh quen thuộc quanh em.","hs":"- HS lắng nghe, đoán tên âm thanh."},{"ten":"2. Khám phá — Âm thanh tự nhiên và nhạc cụ","gv":"- GV cho HS nghe một số âm thanh tự nhiên và âm thanh của sáo trúc; hỏi HS phân biệt.\n- GV giới thiệu sáo trúc: hình dáng, âm sắc trong trẻo, cách tạo âm.","hs":"- HS nghe, phân biệt âm thanh tự nhiên và nhạc cụ.\n- HS quan sát và nghe giới thiệu về sáo trúc."},{"ten":"3. Luyện tập","gv":"- GV cho HS bắt chước một số âm thanh tự nhiên bằng giọng; nghe lại âm sắc sáo trúc.","hs":"- HS mô phỏng âm thanh, nghe và cảm nhận."},{"ten":"4. Vận dụng","gv":"- GV cho HS kể thêm các âm thanh em nghe được trong cuộc sống và phân loại tự nhiên/nhạc cụ.","hs":"- HS kể và phân loại âm thanh."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu đoạn phim quay cận cảnh cho nội dung “Âm thanh tự nhiên và âm thanh của nhạc cụ (sáo trúc)”: nhìn rõ hình dáng, chất liệu, số dây hoặc số lỗ, bàn tay nghệ sĩ đặt ở đâu và làm động tác gì để ra tiếng; GV tua chậm và dừng đúng chỗ đó — chi tiết này tranh in trong sách và một lần nghe trên lớp không cho thấy được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS làm bài tập nghe tương tác có chấm ngay: GV mở lần lượt vài đoạn nhạc ngắn, HS chọn đoạn nào có âm sắc của nhạc cụ vừa học trong “Âm thanh tự nhiên và âm thanh của nhạc cụ (sáo trúc)”; chọn sai thì nghe lại đoạn đó và chọn lần nữa cho tới khi nhận ra đúng.\n⚠ (Miền 4: An toàn) Tư liệu về “Âm thanh tự nhiên và âm thanh của nhạc cụ (sáo trúc)” phải lấy từ trang của nhà xuất bản, nhà hát, bảo tàng hoặc kênh chính thức của nghệ sĩ và tải sẵn về máy trước giờ lên lớp để không lẫn quảng cáo; khi kể lại cho người khác phải nói rõ mình đã xem ở đâu, không nhận tư liệu của người khác là của mình; mở âm lượng vừa đủ nghe.","hs":"- HS nêu được đặc điểm nổi bật của “Âm thanh tự nhiên và âm thanh của nhạc cụ (sáo trúc)” nhờ quan sát tư liệu số và nghe bản thu.\n- HS làm bài tập tương tác, nhận ra âm sắc – nội dung đã học và tự sửa khi chọn sai."}]},
{"lop":1,"mon":"Âm nhạc","tuan":4,"tiet":4,"bai":"Chủ đề 1: Âm thanh kì diệu — Vận dụng — Sáng tạo: To — nhỏ, dài — ngắn; Ôn tập chủ đề 1","yccd":"1. Năng lực âm nhạc\n- Hát thuộc và biểu diễn được bài Vào rừng hoa kết hợp vận động.\n- Bước đầu nhận biết và mô phỏng âm thanh to — nhỏ, dài — ngắn.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: tạo động tác, âm thanh mô phỏng.\n3. Phẩm chất\n- Yêu thiên nhiên, tự tin thể hiện.","dodung":"- GV: đàn phím điện tử (hoặc file nhạc đệm bài Vào rừng hoa), loa, thanh phách, trống con, tranh cảnh rừng hoa, máy chiếu/tivi để mở học liệu số.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo (hai đoạn tre nhỏ, hai chiếc đũa gỗ).","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho cả lớp chơi trò Tiếng vọng của rừng: GV gõ thanh phách một tiếng thật to, cả lớp vỗ tay lại đúng một tiếng to; GV gõ khẽ, cả lớp vỗ khẽ.\n- GV quy ước hiệu lệnh tay: tay giơ cao là hát to, tay hạ thấp là hát thầm; cả lớp hát câu đầu bài Vào rừng hoa theo hiệu lệnh tay của GV.\n- GV hỏi: Vừa rồi tiếng gõ nào to, tiếng nào nhỏ? Khi nào các em hát to, khi nào hát thầm?\n- GV dẫn vào bài: hôm nay lớp mình khám phá âm thanh to — nhỏ, dài — ngắn và ôn lại bài hát Vào rừng hoa.","hs":"- HS nghe tiếng gõ mẫu và vỗ tay lại đúng độ to — nhỏ như GV vừa gõ.\n- HS hát câu đầu bài Vào rừng hoa, hát to khi tay GV giơ cao, hát thầm khi tay GV hạ thấp.\n- HS trả lời: tiếng gõ mạnh là tiếng to, tiếng gõ khẽ là tiếng nhỏ.\n- HS lắng nghe, nhắc lại tên nội dung học."},{"ten":"2. Khám phá — To nhỏ, dài ngắn","gv":"- (10 phút) GV gõ liên tiếp hai tiếng thanh phách, một tiếng gõ mạnh và một tiếng gõ nhẹ, rồi hỏi: Tiếng nào to hơn? Vì sao lại to hơn?\n- GV làm mẫu âm dài — âm ngắn: ngân giọng a kéo dài bằng bốn phách (GV đếm 1-2-3-4 bằng tay), sau đó bật một tiếng a thật ngắn, dứt ngay.\n- GV cho HS mô phỏng âm thanh quen thuộc: tiếng trống trường tùng ngân dài, tiếng gõ cửa cốc cốc ngắn gọn; tiếng sấm to, tiếng lá rơi nhỏ.\n- GV vẽ lên bảng vạch dài cho âm dài, vạch ngắn cho âm ngắn, chữ to cho âm to, chữ nhỏ cho âm nhỏ; GV chỉ vào từng kí hiệu, HS phát ra âm tương ứng.\n- GV chốt: âm to nghe mạnh và rõ, âm nhỏ nghe khẽ; âm dài ngân lâu, âm ngắn dứt nhanh.","hs":"- HS nghe, so sánh và trả lời: tiếng gõ mạnh to hơn vì gõ dùng nhiều sức hơn.\n- HS ngân giọng a kéo dài bốn phách theo tay đếm của GV, rồi bật một tiếng a ngắn.\n- HS mô phỏng tiếng trống ngân dài, tiếng gõ cửa ngắn; nêu thêm tiếng sấm to, tiếng lá rơi nhỏ.\n- HS nhìn kí hiệu trên bảng và phát ra đúng âm to — nhỏ, dài — ngắn.\n- HS nhắc lại kết luận của GV."},{"ten":"3. Luyện tập","gv":"- (12 phút) GV đàn giai điệu cho cả lớp hát ôn bài Vào rừng hoa một lần theo nhạc đệm; GV nhắc HS lấy hơi ở cuối mỗi câu hát, không lấy hơi giữa chừng làm đứt câu.\n- Chỗ nào HS hát chênh cao độ, GV đàn lại nốt đầu của câu đó, hát mẫu chậm hai lần rồi cho HS hát nối câu sai với câu đứng trước cho liền mạch.\n- GV hướng dẫn hát kết hợp gõ đệm theo phách: gõ đều đặn vào phách mạnh của từng nhịp; sau đó chuyển sang gõ theo tiết tấu lời ca, mỗi tiếng hát một tiếng gõ.\n- GV tổ chức chuỗi luyện tập: cả lớp hát một lần, tổ 1 hát thì tổ 2 gõ đệm rồi đổi vai, nhóm 4-6 HS lên trước lớp, cuối cùng 2-3 HS xung phong hát cá nhân.\n- GV gợi ý sắc thái: hai câu đầu hát to, tươi vui; câu cuối hát nhỏ dần như tiếng chim bay xa.","hs":"- HS hát ôn cả bài theo nhạc đệm, lấy hơi đúng chỗ cuối câu.\n- HS hát lại câu còn sai theo mẫu chậm của GV rồi hát nối với câu trước cho đúng cao độ.\n- HS hát kết hợp gõ đệm theo phách, sau đó gõ theo tiết tấu lời ca.\n- HS luyện tập lần lượt theo cả lớp, theo tổ, theo nhóm 4-6 bạn và cá nhân xung phong.\n- HS thể hiện được sắc thái hát to ở câu đầu, hát nhỏ dần ở câu cuối."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- (9 phút) GV chia lớp thành các nhóm 4-6 HS, giao nhiệm vụ mỗi nhóm nghĩ hai động tác phụ hoạ cho bài Vào rừng hoa; GV gợi ý: hai tay đưa lên cao xoè ra như bông hoa nở, chân nhún nhẹ theo phách, hai tay vẫy như cánh bướm bay.\n- GV cho các nhóm tập trong 3 phút rồi lần lượt lên biểu diễn; các bạn ở dưới vỗ tay theo phách cổ vũ.\n- GV nêu tiêu chí để cả lớp cùng nhận xét: thuộc lời, hát đúng giai điệu, hoà giọng cùng nhóm, động tác đều và mạnh dạn tự tin.\n- GV củng cố: Chủ đề 1 các em đã học bài hát nào? Hãy cho một ví dụ về âm thanh dài và một ví dụ về âm thanh ngắn.\n- GV dặn HS về hát bài Vào rừng hoa cho ông bà, bố mẹ nghe và mang thanh phách cho tiết học sau.","hs":"- HS về nhóm 4-6 bạn, cùng bàn và chọn hai động tác phụ hoạ cho bài hát.\n- HS tập theo nhóm rồi lên biểu diễn trước lớp, các bạn ở dưới vỗ tay theo phách.\n- HS nhận xét nhóm bạn theo tiêu chí GV nêu, nói được một điều bạn làm tốt.\n- HS trả lời củng cố: bài Vào rừng hoa; tiếng trống trường ngân dài, tiếng vỗ tay ngắn.\n- HS ghi nhớ nhiệm vụ về nhà và việc chuẩn bị đồ dùng."}]},
{"lop":1,"mon":"Âm nhạc","tuan":5,"tiet":5,"bai":"Chủ đề 2: Việt Nam yêu thương — Học hát: Lá cờ Việt Nam (Lý Trọng — Đỗ Mạnh Thường)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng giai điệu bài Lá cờ Việt Nam.\n- Cảm nhận tính chất vui tươi, tự hào của bài hát.\n- Biết hát kết hợp vỗ tay theo phách.\n2. Năng lực chung\n- Giao tiếp và hợp tác: hát hòa giọng cùng bạn.\n3. Phẩm chất\n- Yêu nước: yêu quý lá cờ Tổ quốc, tự hào về đất nước Việt Nam.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát cùng tên tác giả.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh ảnh lá cờ Việt Nam, thanh phách, thiết bị số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem hình ảnh lá cờ đỏ sao vàng và hỏi: Đây là gì? Em thấy lá cờ ở đâu?\n- GV dẫn vào bài hát.","hs":"- HS quan sát, trả lời: lá cờ Việt Nam, thấy ở trường, ngày lễ."},{"ten":"2. Khám phá — Học hát","gv":"- GV mở hát mẫu cho HS nghe 1-2 lần; đọc lời ca theo câu.\n- GV đàn và bắt nhịp cho HS tập hát từng câu nối tiếp đến hết bài.","hs":"- HS nghe mẫu, đọc lời, tập hát từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài theo nhạc, sửa sai, kết hợp vỗ tay theo phách.","hs":"- HS hát cả bài, vỗ tay theo phách."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cá nhân hát; dặn HS hát cho gia đình nghe.","hs":"- HS biểu diễn, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Lá cờ Việt Nam” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Lý Trọng — Đỗ Mạnh Thường”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Lá cờ Việt Nam” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Lá cờ Việt Nam” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Lá cờ Việt Nam”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."}]},
{"lop":1,"mon":"Âm nhạc","tuan":6,"tiet":6,"bai":"Chủ đề 2: Việt Nam yêu thương — Ôn bài hát Lá cờ Việt Nam; Nghe nhạc: Quốc ca Việt Nam (Văn Cao)","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu bài Lá cờ Việt Nam, kết hợp vận động phụ họa đơn giản.\n- Lắng nghe và cảm nhận không khí trang nghiêm khi nghe Quốc ca Việt Nam.\n- Biết đứng nghiêm trang khi nghe Quốc ca và khi chào cờ.\n2. Năng lực chung\n- Giao tiếp và hợp tác: phối hợp cùng bạn khi vận động.\n3. Phẩm chất\n- Yêu nước: trân trọng Quốc ca, nghiêm túc khi chào cờ.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên tác phẩm và tên tác giả có ghi trong phần chú thích.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh cảnh lễ chào cờ, thanh phách, thiết bị mở học liệu số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát lại bài Lá cờ Việt Nam.","hs":"- HS hát tập thể."},{"ten":"2. Khám phá — Nghe nhạc Quốc ca","gv":"- GV giới thiệu ngắn: Quốc ca là bài Tiến quân ca của nhạc sĩ Văn Cao; khi chào cờ mọi người đứng nghiêm hướng về Quốc kì.\n- GV mở Quốc ca cho HS nghe, hướng dẫn đứng nghiêm trang.","hs":"- HS lắng nghe giới thiệu.\n- HS đứng nghiêm trang nghe Quốc ca."},{"ten":"3. Luyện tập — Ôn bài hát","gv":"- GV cho HS ôn hát Lá cờ Việt Nam, kết hợp vỗ tay theo phách và vận động nhẹ nhàng.","hs":"- HS ôn hát, vận động phụ họa theo GV."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cá nhân biểu diễn; dặn HS nghiêm túc khi chào cờ đầu tuần.","hs":"- HS biểu diễn, ghi nhớ lời dặn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản ghi hình buổi biểu diễn tác phẩm “Quốc ca Việt Nam” (Văn Cao) để HS vừa nghe vừa nhìn thấy người nghệ sĩ đang chơi nhạc cụ nào, ngồi và cầm đàn ra sao; GV tạm dừng đúng lúc để HS chỉ lên màn hình gọi tên nhạc cụ vừa vang lên.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV cho HS đọc phần chú thích dưới đoạn phim: tên tác phẩm, tên tác giả, tên người biểu diễn; HS hiểu bản nhạc nào cũng do một người viết ra, nhắc đến bản nhạc thì phải gọi đúng tên người ấy.\n⚠ (Miền 4: An toàn) GV chọn và tải sẵn đoạn phim về “Quốc ca Việt Nam” trước giờ học rồi mở ngoại tuyến để HS không nhìn thấy quảng cáo và các đoạn phim gợi ý bên cạnh; âm lượng để vừa nghe, HS ngồi cách màn hình vừa tầm mắt và không tự thao tác thiết bị.","hs":"- HS nghe và xem bản ghi hình “Quốc ca Việt Nam”, gọi được tên nhạc cụ đang vang lên trên màn hình.\n- HS nói được tên tác phẩm và tên tác giả có ghi trong phần chú thích."}]},
{"lop":1,"mon":"Âm nhạc","tuan":7,"tiet":7,"bai":"Chủ đề 2: Việt Nam yêu thương — Nhạc cụ: Thanh phách; Gõ đệm theo bài hát","yccd":"1. Năng lực âm nhạc\n- Nhận biết và gọi đúng tên nhạc cụ thanh phách; biết cách cầm và gõ tạo âm thanh.\n- Biết gõ đệm cho bài hát Lá cờ Việt Nam theo phách.\n2. Năng lực chung\n- Tự chủ và tự học: tự luyện tập gõ đệm.\n- Giao tiếp và hợp tác: phối hợp gõ đệm cùng nhóm.\n3. Phẩm chất\n- Chăm chỉ: kiên trì luyện tập nhạc cụ.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS cầm và gõ được nhạc cụ Thanh phách đúng cách sau khi xem phim cận cảnh.","dodung":"- GV: thanh phách đủ cho các nhóm, đàn phím điện tử hoặc file nhạc đệm bài Lá cờ Việt Nam, loa, tranh nhạc cụ gõ, máy chiếu/tivi để mở học liệu số.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV đàn giai điệu câu hát mở đầu bài Lá cờ Việt Nam và hỏi: Đó là câu hát trong bài nào các em vừa học?\n- GV bắt nhịp cho cả lớp hát trọn bài kết hợp vỗ tay theo phách, nhắc HS lấy hơi sau tiếng cuối mỗi câu hát.\n- GV cho HS đứng tại chỗ hát lần hai, nhún chân nhẹ theo phách để tạo khí thế.\n- GV dẫn vào bài: hôm nay lớp mình làm quen với một nhạc cụ gõ có tên là thanh phách.","hs":"- HS nghe giai điệu và trả lời: bài Lá cờ Việt Nam.\n- HS hát cả bài kết hợp vỗ tay theo phách, lấy hơi đúng chỗ cuối câu.\n- HS đứng hát lần hai, nhún chân nhẹ theo phách.\n- HS lắng nghe và nhắc lại tên nhạc cụ sắp được học."},{"ten":"2. Khám phá — Giới thiệu thanh phách","gv":"- (9 phút) GV đưa thanh phách thật cho HS quan sát: hai thanh tre (hoặc gỗ) dài bằng nhau, nhẵn tay; gõ vào nhau phát ra tiếng cách cách khô, gọn, không ngân dài.\n- GV làm mẫu tư thế cầm: tay trái cầm một thanh, lòng bàn tay hơi ngửa, các ngón giữ lỏng để thanh phách còn rung được; tay phải cầm thanh còn lại gõ xuống mặt thanh bên trái.\n- GV gõ mẫu chậm hai lần, sau đó gõ theo tiếng đếm 1-2, 1-2 cho HS nghe tiếng đều nhau.\n- GV nêu lỗi HS hay mắc và cách sửa: nắm quá chặt làm tiếng bị đục thì nới lỏng ngón tay; gõ quá mạnh làm tiếng chát và đau tay thì gõ vừa lực; gõ vào cạnh thanh nên tiếng nhỏ thì chỉnh cho gõ đúng mặt thanh.","hs":"- HS quan sát, sờ thử thanh phách và nói được: làm bằng tre, hai thanh bằng nhau, tiếng nghe cách cách.\n- HS đặt tay theo mẫu, giữ thanh phách lỏng tay và gõ thử vài tiếng.\n- HS gõ theo tiếng đếm 1-2 của GV cho tiếng đều.\n- HS nhận ra lỗi cầm chặt, gõ mạnh của mình và sửa lại theo hướng dẫn."},{"ten":"3. Luyện tập — Gõ đệm","gv":"- (10 phút) GV cho cả lớp gõ theo tiếng đếm 1-2 trong khoảng một phút cho quen tay, yêu cầu gõ nhẹ, đều, không nhanh dần.\n- GV hát bài Lá cờ Việt Nam thật chậm và gõ mẫu theo phách, gõ đúng vào những tiếng rơi vào phách mạnh của mỗi nhịp cho HS nghe rõ.\n- GV cho HS vừa hát vừa gõ đệm theo phách cả bài, sau đó chuyển sang gõ theo tiết tấu lời ca, mỗi tiếng hát một tiếng gõ.\n- GV sửa sai: nhóm nào gõ nhanh dần thì GV đếm to giữ nhịp; bạn nào gõ lệch phách thì GV đứng cạnh gõ cùng vài nhịp rồi buông cho HS tự giữ.","hs":"- HS gõ theo tiếng đếm, giữ tiếng gõ đều và nhẹ.\n- HS nghe mẫu và nhận ra tiếng hát nào cần gõ vào.\n- HS vừa hát vừa gõ đệm theo phách, sau đó gõ theo tiết tấu lời ca.\n- HS gõ chậm lại theo tiếng đếm của GV khi bị nhanh dần."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV chia lớp thành 3 tổ luân phiên: tổ 1 hát, tổ 2 gõ đệm theo phách, tổ 3 vỗ tay theo nhịp; sau mỗi lượt thì đổi vai cho nhau.\n- GV mời 2-3 nhóm 4-6 HS lên trước lớp vừa hát vừa gõ đệm, khuyến khích HS xung phong gõ đệm một mình cho cả lớp hát.\n- GV nêu tiêu chí nhận xét: gõ đúng phách, gõ đều không nhanh dần, cầm thanh phách đúng cách, hát hoà giọng và mạnh dạn tự tin.\n- GV dặn HS giữ gìn thanh phách, về nhà tập gõ đệm cho bài hát và mang nhạc cụ gõ cho tiết sau.","hs":"- HS thực hiện theo tổ, đổi vai hát, gõ đệm và vỗ tay theo nhịp.\n- HS lên biểu diễn theo nhóm, một số bạn xung phong gõ đệm cá nhân.\n- HS nhận xét bạn theo tiêu chí GV nêu.\n- HS ghi nhớ việc luyện tập ở nhà và giữ gìn nhạc cụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu đoạn phim quay cận cảnh nhạc cụ Thanh phách: nhìn rõ hình dáng, chất liệu, cách cầm và cách gõ sao cho ra đúng tiếng; GV tua chậm đúng động tác khó, cho xem lại hai ba lần rồi mới phát nhạc cụ thật để HS làm theo.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV thu âm tiếng gõ Thanh phách của từng tổ rồi mở lại cho cả lớp nghe; HS nghe ra tổ nào gõ đều, tổ nào còn lúc nhanh lúc chậm — nghe lại bản thu giúp HS nhận ra điều mà lúc đang gõ không nhận ra được.\n⚠ (Miền 4: An toàn) Cầm Thanh phách đúng cách, gõ vừa lực, không đập mạnh xuống bàn và không chĩa vào người bạn; GV thao tác máy chiếu và điện thoại, HS không tự cầm thiết bị; bản thu tiếng gõ của lớp chỉ mở trong giờ học, không gửi ra ngoài lớp.","hs":"- HS cầm và gõ được nhạc cụ Thanh phách đúng cách sau khi xem phim cận cảnh.\n- HS nghe lại bản thu tiếng gõ của tổ và chỉ ra chỗ gõ chưa đều."}]},
{"lop":1,"mon":"Âm nhạc","tuan":8,"tiet":8,"bai":"Chủ đề 2: Việt Nam yêu thương — Vận dụng — Sáng tạo; Ôn tập chủ đề 2","yccd":"1. Năng lực âm nhạc\n- Hát thuộc và biểu diễn được bài Lá cờ Việt Nam kết hợp vận động, gõ đệm.\n- Củng cố kĩ năng gõ thanh phách và cảm nhận tính chất tự hào.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: nghĩ động tác phụ họa đơn giản.\n3. Phẩm chất\n- Yêu nước, tự tin thể hiện.","dodung":"- GV: đàn phím điện tử hoặc file nhạc đệm, loa, thanh phách, trống con, tranh lá cờ Tổ quốc, máy chiếu/tivi để mở học liệu số.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS chơi trò Nghe giai điệu đoán tên bài hát: GV đàn (hoặc mở nhạc không lời) hai câu mở đầu của bài Vào rừng hoa và bài Lá cờ Việt Nam, mỗi câu một lần.\n- GV quy định luật chơi: bạn nào biết thì giơ tay, không nói leo; đoán đúng thì cả lớp vỗ tay ba tiếng.\n- GV hỏi thêm: Bài hát nào có hình ảnh lá cờ đỏ sao vàng? Bài hát ấy hát nhanh hay chậm, vui hay êm dịu?\n- GV dẫn vào bài: tiết này lớp mình ôn tập lại chủ đề Việt Nam yêu thương và sáng tạo động tác phụ hoạ.","hs":"- HS lắng nghe giai điệu, giơ tay và đoán đúng tên hai bài hát đã học.\n- HS thực hiện đúng luật chơi, vỗ tay khen bạn đoán đúng.\n- HS trả lời: bài Lá cờ Việt Nam, bài hát vui tươi, nhịp đi vừa phải.\n- HS lắng nghe, nhắc lại nội dung tiết học."},{"ten":"2. Khám phá","gv":"- (7 phút) GV cùng HS nhắc lại nội dung chủ đề 2 bằng ba câu hỏi: Chủ đề 2 có tên là gì? Các em đã học bài hát nào? Đã làm quen nhạc cụ gõ nào?\n- GV cho HS nhắc lại cách cầm thanh phách và gõ thử ba tiếng để kiểm tra tư thế tay.\n- GV cho HS xem lại tranh lá cờ Tổ quốc và hỏi: Lá cờ Việt Nam có màu gì, ở giữa có hình gì? Khi chào cờ các em phải làm thế nào?\n- GV chốt: chủ đề 2 giúp các em yêu quê hương, đất nước; hát bài Lá cờ Việt Nam cần thể hiện tình cảm trang trọng, tự hào.","hs":"- HS nhắc lại: chủ đề Việt Nam yêu thương, bài hát Lá cờ Việt Nam, nhạc cụ thanh phách.\n- HS cầm thanh phách đúng tư thế và gõ thử ba tiếng.\n- HS trả lời: lá cờ màu đỏ, ở giữa có ngôi sao vàng năm cánh; khi chào cờ phải đứng nghiêm.\n- HS lắng nghe và nhắc lại tình cảm cần thể hiện khi hát."},{"ten":"3. Luyện tập","gv":"- (13 phút) GV đàn cho cả lớp hát ôn bài Lá cờ Việt Nam một lần, nhắc HS lấy hơi ở cuối mỗi câu và hát rõ lời, không hét.\n- Chỗ HS hát chênh cao độ, GV đàn lại nốt đầu câu đó, hát mẫu chậm rồi cho HS hát nối câu sai với câu trước cho liền mạch.\n- GV lần lượt cho HS luyện ba hình thức gõ đệm: gõ theo phách, gõ theo nhịp (chỉ gõ vào phách mạnh) và gõ theo tiết tấu lời ca.\n- GV tổ chức chuỗi luyện tập: cả lớp hát một lần, luyện theo tổ (tổ hát - tổ gõ đệm rồi đổi vai), nhóm 4-6 HS, sau cùng mời cá nhân xung phong.\n- GV tổ chức trò chơi hát to - hát thầm: tay GV giơ cao thì cả lớp hát to, tay hạ thấp thì hát thầm nhưng vẫn giữ đúng nhịp.","hs":"- HS hát ôn cả bài theo nhạc đệm, lấy hơi đúng chỗ, hát rõ lời.\n- HS hát lại câu còn chênh cao độ theo mẫu chậm của GV.\n- HS thực hiện ba kiểu gõ đệm: theo phách, theo nhịp và theo tiết tấu lời ca.\n- HS luyện tập theo cả lớp, theo tổ, theo nhóm 4-6 bạn và cá nhân.\n- HS chơi trò hát to - hát thầm, giữ đúng nhịp khi hát thầm."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- (11 phút) GV chia nhóm 4-6 HS, giao nhiệm vụ nghĩ hai đến ba động tác phụ hoạ; GV gợi ý: hai tay đưa lên cao vẫy như lá cờ bay, tay phải đặt ngang ngực khi hát câu về ngôi sao vàng, chân nhún nhẹ theo phách.\n- GV cho các nhóm tập 3 phút rồi lần lượt lên biểu diễn theo tốp ca, một bạn trong nhóm gõ thanh phách đệm.\n- GV nêu tiêu chí nhận xét: thuộc lời, hát đúng giai điệu, hoà giọng, gõ đệm đúng phách, động tác đều và tự tin.\n- GV củng cố chủ đề bằng câu hỏi: Bài hát nhắc các em nhớ đến điều gì? Em cần làm gì để tỏ lòng yêu Tổ quốc?\n- GV dặn HS về hát và biểu diễn cho người thân xem, chuẩn bị SGK và thanh phách cho tiết ôn tập giữa học kì.","hs":"- HS về nhóm bàn bạc và chọn động tác phụ hoạ phù hợp với lời bài hát.\n- HS tập theo nhóm rồi lên biểu diễn, có bạn gõ thanh phách đệm cho nhóm.\n- HS nhận xét nhóm bạn theo tiêu chí GV nêu.\n- HS trả lời: bài hát nhắc nhớ lá cờ Tổ quốc; cần chăm học, đứng nghiêm khi chào cờ.\n- HS ghi nhớ nhiệm vụ về nhà và đồ dùng cần chuẩn bị."}]},
{"lop":1,"mon":"Âm nhạc","tuan":9,"tiet":9,"bai":"Ôn tập giữa học kì I — Ôn các bài hát và nội dung chủ đề 1, 2","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu các bài Vào rừng hoa, Lá cờ Việt Nam.\n- Củng cố kĩ năng gõ đệm theo phách; đọc ba nốt Đô-Rê-Mi; phân biệt to-nhỏ, dài-ngắn.\n2. Năng lực chung\n- Tự chủ và tự học: tự đánh giá kết quả học tập.\n3. Phẩm chất\n- Chăm chỉ, tự tin biểu diễn.","dodung":"- GV: đàn phím điện tử hoặc file nhạc đệm, loa, thanh phách, trống con, thăm ghi tên bài hát, tranh kí hiệu bàn tay Đô - Rê - Mi, máy chiếu/tivi.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS chơi trò Nghe giai điệu đoán tên bài hát: GV đàn câu mở đầu của bài Vào rừng hoa và bài Lá cờ Việt Nam, mỗi câu một lần, HS giơ tay đoán.\n- GV nâng độ khó: GV chỉ gõ tiết tấu lời ca của một câu hát bằng thanh phách, HS nghe tiết tấu và đoán đó là câu trong bài nào.\n- GV khen ngợi, cho cả lớp vỗ tay theo phách hát lại một trong hai bài để vào không khí ôn tập.\n- GV nêu nhiệm vụ tiết học: ôn lại các bài hát, cách gõ đệm, ba nốt Đô - Rê - Mi và các âm thanh to - nhỏ, dài - ngắn.","hs":"- HS lắng nghe giai điệu, giơ tay và đoán đúng tên bài hát.\n- HS nghe tiết tấu gõ và đoán được câu hát tương ứng.\n- HS hát lại một bài kết hợp vỗ tay theo phách.\n- HS lắng nghe, nhắc lại nhiệm vụ của tiết ôn tập."},{"ten":"2. Khám phá — Hệ thống lại","gv":"- (7 phút) GV treo bảng ôn tập và cùng HS nhắc lại theo từng chủ đề: chủ đề 1 Âm thanh kì diệu có bài Vào rừng hoa và nội dung âm to - nhỏ, dài - ngắn; chủ đề 2 Việt Nam yêu thương có bài Lá cờ Việt Nam, nhạc cụ thanh phách và ba nốt Đô - Rê - Mi.\n- GV hỏi nhanh từng nội dung: Bài Vào rừng hoa do ai sáng tác? Thanh phách cầm thế nào cho đúng? Nốt nào thấp nhất trong ba nốt đã học?\n- GV cho HS làm lại ba kí hiệu bàn tay Đô - Rê - Mi và đọc thang âm đi lên Đô - Rê - Mi, đi xuống Mi - Rê - Đô.\n- GV chốt lại những nội dung sẽ ôn luyện và đánh giá trong tiết học.","hs":"- HS nhắc lại tên hai chủ đề, tên bài hát và các nội dung đã học ở mỗi chủ đề.\n- HS trả lời: bài Vào rừng hoa của nhạc sĩ Việt Anh; thanh phách cầm lỏng tay; nốt Đô thấp nhất.\n- HS làm kí hiệu bàn tay và đọc thang âm đi lên, đi xuống theo tay GV.\n- HS lắng nghe, ghi nhớ nội dung ôn tập."},{"ten":"3. Luyện tập","gv":"- (13 phút) GV cho cả lớp hát ôn lần lượt từng bài: bài Vào rừng hoa hát kết hợp vỗ tay theo phách, bài Lá cờ Việt Nam hát kết hợp gõ thanh phách theo nhịp.\n- GV nghe và sửa từng lỗi cụ thể: hát sai lời thì GV đọc lại lời ca theo tiết tấu; hát chênh cao độ thì GV đàn lại nốt đầu câu, hát mẫu chậm rồi cho HS hát nối câu sai với câu trước.\n- GV cho HS ôn đọc nhạc: đọc ba nốt Đô - Rê - Mi theo kí hiệu bàn tay, đọc thang âm đi lên rồi đi xuống, đọc kết hợp gõ phách đều tay.\n- GV ôn nhanh nội dung to - nhỏ, dài - ngắn: GV gõ hoặc ngân một âm, HS giơ tay cao nếu là âm to, giơ tay ngang nếu là âm nhỏ; dang hai tay rộng nếu là âm dài, chụm tay nếu là âm ngắn.\n- GV tổ chức luyện tập theo chuỗi cả lớp, tổ, nhóm 4-6 HS rồi cá nhân.","hs":"- HS hát ôn từng bài kết hợp vỗ tay theo phách và gõ thanh phách theo nhịp.\n- HS sửa lại lời và cao độ những câu còn sai theo mẫu của GV.\n- HS đọc ba nốt Đô - Rê - Mi theo kí hiệu bàn tay, đọc thang âm đi lên đi xuống và gõ phách.\n- HS phản xạ đúng bằng động tác tay khi nghe âm to - nhỏ, dài - ngắn.\n- HS luyện tập theo cả lớp, tổ, nhóm và cá nhân."},{"ten":"4. Vận dụng","gv":"- (11 phút) GV cho các nhóm 4-6 HS bốc thăm bài biểu diễn; trong thăm ghi sẵn tên bài hát và hình thức trình bày (hát kết hợp gõ đệm hoặc hát kết hợp vận động).\n- GV cho các nhóm chuẩn bị 2 phút, sau đó lần lượt lên biểu diễn trước lớp; nhóm ở dưới lắng nghe để nhận xét.\n- GV nêu rõ tiêu chí đánh giá trước khi biểu diễn: thuộc lời, hát đúng giai điệu, hoà giọng cùng nhóm, gõ đệm đúng phách, mạnh dạn tự tin.\n- GV nhận xét theo hướng động viên sự tiến bộ, khen cụ thể từng nhóm một điểm mạnh và gợi ý một điểm cần luyện thêm.\n- GV dặn HS ôn lại các bài hát ở nhà, chuẩn bị SGK và thanh phách cho chủ đề Mái trường thân yêu.","hs":"- HS bốc thăm theo nhóm và nhận nhiệm vụ biểu diễn.\n- HS chuẩn bị trong nhóm rồi lên biểu diễn trước lớp.\n- HS tự nhận xét nhóm mình và nhận xét nhóm bạn theo năm tiêu chí GV nêu.\n- HS lắng nghe nhận xét của GV, ghi nhớ điều cần luyện thêm.\n- HS ghi nhớ nhiệm vụ ôn tập ở nhà và đồ dùng cần chuẩn bị."}]},
{"lop":1,"mon":"Âm nhạc","tuan":10,"tiet":10,"bai":"Chủ đề 3: Mái trường thân yêu — Học hát: Lớp Một thân yêu (Bùi Anh Tôn)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng giai điệu bài Lớp Một thân yêu.\n- Cảm nhận tính chất vui tươi, hồn nhiên của bài hát về mái trường.\n2. Năng lực chung\n- Giao tiếp và hợp tác: hát hòa giọng cùng bạn.\n3. Phẩm chất\n- Yêu trường lớp, yêu quý thầy cô và bạn bè.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát cùng tên tác giả.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh cảnh trường lớp, thanh phách, thiết bị số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem tranh cảnh lớp học, hỏi các em thích gì ở lớp mình, dẫn vào bài.","hs":"- HS quan sát, trả lời."},{"ten":"2. Khám phá — Học hát","gv":"- GV mở hát mẫu, đọc lời ca theo câu.\n- GV đàn và bắt nhịp cho HS tập hát từng câu đến hết bài.","hs":"- HS nghe mẫu, đọc lời, tập hát từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài, sửa sai, kết hợp vỗ tay theo phách.","hs":"- HS hát cả bài, vỗ tay theo phách."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cá nhân hát; dặn HS hát cho gia đình nghe.","hs":"- HS biểu diễn, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Lớp Một thân yêu” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Bùi Anh Tôn”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Lớp Một thân yêu” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Lớp Một thân yêu” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Lớp Một thân yêu”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."}]},
{"lop":1,"mon":"Âm nhạc","tuan":11,"tiet":11,"bai":"Chủ đề 3: Mái trường thân yêu — Ôn bài hát Lớp Một thân yêu; Nghe nhạc: Những bông hoa những bài ca (Hoàng Long)","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu, kết hợp vận động phụ họa.\n- Lắng nghe và cảm nhận giai điệu vui tươi của bài Những bông hoa những bài ca; biết vận động theo nhạc.\n2. Năng lực chung\n- Tự chủ: mạnh dạn nêu cảm nhận.\n3. Phẩm chất\n- Yêu trường lớp, biết ơn thầy cô.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên tác phẩm và tên tác giả có ghi trong phần chú thích.","dodung":"- GV: đàn phím điện tử hoặc file nhạc đệm, loa, tranh minh hoạ mái trường, thanh phách, bản ghi bài Những bông hoa những bài ca tải sẵn, máy chiếu/tivi.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV đàn giai điệu câu mở đầu bài Lớp Một thân yêu và hỏi: Đây là câu hát trong bài nào?\n- GV bắt nhịp cho cả lớp hát trọn bài kết hợp vỗ tay theo phách, nhắc HS lấy hơi ở cuối mỗi câu hát.\n- GV hỏi: Bài hát nói về ai, về nơi nào? Em thích nhất câu hát nào trong bài?\n- GV dẫn vào bài: tiết này lớp mình ôn lại bài hát và cùng nghe một bài hát rất hay về thầy cô.","hs":"- HS nghe giai điệu và trả lời đúng tên bài Lớp Một thân yêu.\n- HS hát cả bài kết hợp vỗ tay theo phách, lấy hơi đúng chỗ.\n- HS trả lời: bài hát nói về lớp học, về thầy cô và bạn bè.\n- HS lắng nghe, nhắc lại nội dung tiết học."},{"ten":"2. Khám phá — Nghe nhạc","gv":"- (11 phút) Trước khi nghe, GV nêu hai câu hỏi định hướng và ghi lên bảng: Bài hát vui hay êm dịu, nhanh hay chậm? Bài hát nhắc đến những ai trong nhà trường?\n- Lần nghe thứ nhất: GV mở bản ghi bài Những bông hoa những bài ca, HS ngồi ngay ngắn, lắng nghe trọn vẹn, không nói chuyện.\n- Lần nghe thứ hai: GV cho HS nghe kết hợp vận động nhẹ nhàng tại chỗ, đưa người sang trái sang phải hoặc vỗ tay khẽ theo nhịp.\n- Sau khi nghe, GV hỏi lại hai câu định hướng, dự kiến HS trả lời: bài hát vui tươi, nhịp nhanh vừa; bài hát nhắc đến các thầy cô giáo và các bạn học sinh mang hoa tặng thầy cô.\n- GV chốt: bài hát của nhạc sĩ Hoàng Long nói về lòng biết ơn thầy cô, tình cảm ấy được thể hiện qua giai điệu tươi vui, rộn ràng.","hs":"- HS đọc và ghi nhớ hai câu hỏi định hướng trước khi nghe.\n- HS ngồi ngay ngắn, nghe trọn bài lần thứ nhất.\n- HS nghe lần hai kết hợp vận động nhẹ nhàng hoặc vỗ tay khẽ theo nhịp.\n- HS trả lời: bài hát vui tươi, nhịp nhanh vừa, nhắc đến thầy cô và các bạn mang hoa tặng thầy cô.\n- HS lắng nghe và nhắc lại tên tác phẩm cùng tên tác giả."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV cho HS ôn hát bài Lớp Một thân yêu theo nhạc đệm; chỗ HS hát chênh cao độ, GV đàn lại nốt đầu câu, hát mẫu chậm rồi cho HS hát nối câu sai với câu trước.\n- GV hướng dẫn ba động tác vận động phụ hoạ: câu 1 hai tay đưa lên ngang ngực rồi mở ra, câu 2 tay phải chỉ về phía bảng như chỉ lớp học, câu cuối hai tay đặt lên ngực thể hiện tình cảm; chân nhún nhẹ theo phách.\n- GV cho HS luyện theo chuỗi: cả lớp cùng làm, sau đó tổ 1 hát tổ 2 vận động rồi đổi vai, tiếp đến nhóm 4-6 HS.\n- GV mở lại bài nghe nhạc một lần nữa, cho HS đứng vận động tự do theo nhạc.","hs":"- HS ôn hát cả bài theo nhạc đệm, sửa lại những câu còn chênh cao độ.\n- HS làm theo ba động tác phụ hoạ, chân nhún nhẹ theo phách.\n- HS luyện tập theo cả lớp, theo tổ và theo nhóm 4-6 bạn.\n- HS đứng vận động nhẹ nhàng theo bài nghe nhạc."},{"ten":"4. Vận dụng","gv":"- (6 phút) GV mời 2-3 nhóm 4-6 HS lên biểu diễn bài Lớp Một thân yêu kết hợp vận động phụ hoạ, khuyến khích một vài HS xung phong hát cá nhân.\n- GV nêu tiêu chí nhận xét: thuộc lời, hát đúng giai điệu, hoà giọng, động tác đều và mạnh dạn tự tin.\n- GV củng cố: Hôm nay các em được nghe bài hát nào, của nhạc sĩ nào? Em sẽ làm gì để tỏ lòng biết ơn thầy cô?\n- GV dặn HS về hát cho người thân nghe và chuẩn bị SGK, thanh phách cho tiết đọc nhạc Ban nhạc Đô - Rê - Mi.","hs":"- HS lên biểu diễn theo nhóm, một số bạn xung phong hát cá nhân.\n- HS nhận xét bạn theo tiêu chí GV nêu.\n- HS trả lời: bài Những bông hoa những bài ca của nhạc sĩ Hoàng Long; sẽ chăm ngoan, học giỏi, lễ phép với thầy cô.\n- HS ghi nhớ nhiệm vụ về nhà và đồ dùng cần chuẩn bị."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản ghi hình buổi biểu diễn tác phẩm “Những bông hoa những bài ca” (Hoàng Long) để HS vừa nghe vừa nhìn thấy người nghệ sĩ đang chơi nhạc cụ nào, ngồi và cầm đàn ra sao; GV tạm dừng đúng lúc để HS chỉ lên màn hình gọi tên nhạc cụ vừa vang lên.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV cho HS đọc phần chú thích dưới đoạn phim: tên tác phẩm, tên tác giả, tên người biểu diễn; HS hiểu bản nhạc nào cũng do một người viết ra, nhắc đến bản nhạc thì phải gọi đúng tên người ấy.\n⚠ (Miền 4: An toàn) GV chọn và tải sẵn đoạn phim về “Những bông hoa những bài ca” trước giờ học rồi mở ngoại tuyến để HS không nhìn thấy quảng cáo và các đoạn phim gợi ý bên cạnh; âm lượng để vừa nghe, HS ngồi cách màn hình vừa tầm mắt và không tự thao tác thiết bị.","hs":"- HS nghe và xem bản ghi hình “Những bông hoa những bài ca”, gọi được tên nhạc cụ đang vang lên trên màn hình.\n- HS nói được tên tác phẩm và tên tác giả có ghi trong phần chú thích."}]},
{"lop":1,"mon":"Âm nhạc","tuan":12,"tiet":12,"bai":"Chủ đề 3: Mái trường thân yêu — Đọc nhạc: Ban nhạc Đô — Rê — Mi","yccd":"1. Năng lực âm nhạc\n- Đọc đúng cao độ ba nốt Đô — Rê — Mi theo kí hiệu bàn tay.\n- Đọc được bài Ban nhạc Đô — Rê — Mi kết hợp gõ đệm đơn giản.\n2. Năng lực chung\n- Tự chủ và tự học: tự luyện đọc nốt.\n3. Phẩm chất\n- Chăm chỉ luyện tập.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS đọc đúng cao độ “Ban nhạc Đô — Rê — Mi” nhờ nghe mẫu từ đàn phím.","dodung":"- GV: đàn phím điện tử, loa, tranh kí hiệu bàn tay ba nốt Đô - Rê - Mi, bảng phụ chép bài đọc nhạc, thanh phách, máy chiếu/tivi.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV treo tranh kí hiệu bàn tay và nhắc lại: nắm bàn tay là nốt Đô, bàn tay chếch lên là nốt Rê, bàn tay để ngang là nốt Mi; vị trí tay càng cao thì nốt càng cao.\n- GV đàn mẫu ba nốt rồi làm kí hiệu bàn tay, cả lớp đọc theo thang âm đi lên Đô - Rê - Mi và đi xuống Mi - Rê - Đô.\n- GV chơi trò đố nhanh: GV làm một kí hiệu bàn tay bất kì, HS đọc ngay tên nốt đó.\n- GV dẫn vào bài đọc nhạc Ban nhạc Đô - Rê - Mi.","hs":"- HS quan sát tranh, nhắc lại ba kí hiệu bàn tay tương ứng ba nốt.\n- HS đọc thang âm đi lên và đi xuống theo tay GV, đọc đúng cao độ.\n- HS nhìn kí hiệu và đọc ngay tên nốt trong trò chơi đố nhanh.\n- HS lắng nghe, nhắc lại tên bài đọc nhạc."},{"ten":"2. Khám phá — Ban nhạc Đô-Rê-Mi","gv":"- (10 phút) GV treo bảng phụ bài đọc nhạc, chỉ cho HS thấy bài gồm bốn câu, mỗi câu là một dòng nhạc ngắn; GV chỉ từng nốt và cho HS gọi tên nốt.\n- GV đàn lấy cao độ chuẩn rồi đọc mẫu cả bài một lần với tốc độ vừa phải, kết hợp làm kí hiệu bàn tay.\n- GV dạy theo lối móc xích: đọc mẫu câu 1 hai lần rồi bắt nhịp cho HS đọc lại; làm tương tự với câu 2, sau đó ghép câu 1 với câu 2; dạy tiếp câu 3, câu 4 rồi ghép cả bài.\n- GV nhắc HS lấy hơi sau mỗi câu, giữ hơi đều để tiếng đọc không bị hụt ở cuối câu.","hs":"- HS quan sát bảng phụ, đếm được bốn câu và gọi đúng tên các nốt.\n- HS nghe GV đọc mẫu cả bài kết hợp kí hiệu bàn tay.\n- HS đọc từng câu theo mẫu, ghép câu 1 với câu 2, rồi ghép cả bài.\n- HS lấy hơi sau mỗi câu, đọc đều tiếng đến cuối câu."},{"ten":"3. Luyện tập","gv":"- (11 phút) GV cho cả lớp đọc cả bài hai lần: lần một chỉ đọc kết hợp kí hiệu bàn tay, lần hai đọc kết hợp gõ phách bằng thanh phách.\n- GV sửa sai theo cách: chỗ nào HS đọc chênh cao độ thì GV đàn lại nốt đầu của câu đó, đọc mẫu chậm hai lần rồi cho HS đọc nối câu sai với câu đứng trước.\n- GV luyện theo chuỗi: cả lớp đọc, tổ 1 đọc tổ 2 gõ phách rồi đổi vai, nhóm 4-6 HS đọc, cuối cùng mời cá nhân xung phong.\n- GV lưu ý HS gõ phách đều tay, không gõ nhanh dần và không gõ to lấn tiếng đọc.","hs":"- HS đọc cả bài kết hợp kí hiệu bàn tay, sau đó đọc kết hợp gõ phách.\n- HS đọc lại câu còn chênh cao độ theo mẫu chậm của GV rồi đọc nối với câu trước.\n- HS luyện đọc theo cả lớp, theo tổ, theo nhóm 4-6 bạn và cá nhân.\n- HS gõ phách đều tay, giữ tiếng gõ nhẹ hơn tiếng đọc."},{"ten":"4. Vận dụng","gv":"- (5 phút) GV tổ chức trò chơi Ban nhạc nhỏ: mỗi tổ nhận một nốt (tổ 1 nốt Đô, tổ 2 nốt Rê, tổ 3 nốt Mi); GV chỉ vào tổ nào thì tổ đó đọc vang tên nốt của mình đúng cao độ.\n- GV mời 2-3 nhóm hoặc cá nhân đọc lại cả bài kết hợp làm kí hiệu bàn tay trước lớp.\n- GV nêu tiêu chí nhận xét: đọc đúng cao độ, đọc đều nhịp, làm kí hiệu bàn tay đúng, mạnh dạn tự tin.\n- GV dặn HS về đọc lại bài cho người thân nghe và chuẩn bị đồ dùng cho tiết vận dụng - sáng tạo của chủ đề 3.","hs":"- HS chơi trò Ban nhạc nhỏ, đọc đúng cao độ nốt của tổ mình khi GV chỉ.\n- HS đọc lại cả bài kết hợp kí hiệu bàn tay theo nhóm hoặc cá nhân.\n- HS nhận xét bạn theo tiêu chí GV nêu.\n- HS ghi nhớ nhiệm vụ về nhà và đồ dùng cần chuẩn bị."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV dùng đàn phím điện tử hoặc phần mềm đàn phím trên máy tính để lấy cao độ chuẩn cho “Ban nhạc Đô — Rê — Mi”: bấm từng nốt cho HS nghe rõ, bấm chậm cả câu, rồi bấm lại đúng nốt mà HS còn đọc chênh — cao độ lấy từ đàn chuẩn hơn lấy từ giọng người vì không bị lệch theo hơi thở.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở trò chơi nghe nốt trên máy: máy phát một nốt, HS giơ kí hiệu bàn tay tương ứng, GV bấm lại nốt đó để cả lớp cùng kiểm tra ngay đúng hay sai rồi đọc lại — HS biết mình sai ở nốt nào ngay tại chỗ chứ không chờ hết giờ.\n⚠ (Miền 4: An toàn) GV thao tác đàn và máy tính, HS chỉ nghe và đọc theo, không tự bấm vào thiết bị của GV; mở âm lượng vừa đủ nghe để không hại tai; chỉ dùng phần mềm GV đã cài sẵn, không mở phần mềm hay trang khác trong giờ học.","hs":"- HS đọc đúng cao độ “Ban nhạc Đô — Rê — Mi” nhờ nghe mẫu từ đàn phím.\n- HS nhận ra ngay nốt mình đọc còn chênh và đọc lại cho đúng."}]},
{"lop":1,"mon":"Âm nhạc","tuan":13,"tiet":13,"bai":"Chủ đề 3: Mái trường thân yêu — Vận dụng — Sáng tạo: To — nhỏ, cao — thấp; Ôn tập chủ đề 3","yccd":"1. Năng lực âm nhạc\n- Hát thuộc và biểu diễn bài Lớp Một thân yêu kết hợp vận động.\n- Bước đầu nhận biết âm to — nhỏ, cao — thấp và vận động theo.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: nghĩ động tác phụ họa.\n3. Phẩm chất\n- Yêu trường lớp, tự tin thể hiện.","dodung":"- GV: đàn phím điện tử hoặc file nhạc đệm, loa, thanh phách, trống con, tranh minh hoạ mái trường, máy chiếu/tivi để mở học liệu số.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho cả lớp chơi trò Cao - thấp, to - nhỏ: GV đàn một nốt cao thì HS đứng nhón chân giơ tay lên cao, GV đàn nốt thấp thì HS ngồi xuống ghế và hạ tay.\n- GV đổi hiệu lệnh sang to - nhỏ: GV gõ trống con một tiếng mạnh thì HS vỗ tay to, gõ tiếng khẽ thì HS xoa hai bàn tay vào nhau thật nhẹ.\n- GV hỏi: Âm thanh nào nghe cao hơn, âm thanh nào nghe to hơn? Làm sao em biết được?\n- GV dẫn vào bài: tiết này lớp mình khám phá âm cao - thấp, to - nhỏ và ôn tập chủ đề Mái trường thân yêu.","hs":"- HS phản xạ đúng động tác khi nghe nốt cao và nốt thấp.\n- HS vỗ tay to khi nghe tiếng gõ mạnh, xoa tay nhẹ khi nghe tiếng gõ khẽ.\n- HS trả lời theo cảm nhận: tiếng đàn ở phía tay phải nghe cao hơn, tiếng gõ mạnh nghe to hơn.\n- HS lắng nghe, nhắc lại nội dung tiết học."},{"ten":"2. Khám phá — To nhỏ, cao thấp","gv":"- (10 phút) GV đàn hai nốt cách xa nhau (một nốt trầm, một nốt cao) và hỏi HS nốt nào cao hơn; GV vừa đàn vừa đưa tay lên cao hoặc hạ xuống thấp để HS thấy được độ cao của âm.\n- GV cho HS mô phỏng bằng giọng: tiếng chim hót cao và nhỏ, tiếng trống trường thấp và to, tiếng mèo kêu cao, tiếng bò kêu thấp.\n- GV lưu ý HS phân biệt hai khái niệm dễ nhầm: to - nhỏ là độ mạnh của âm thanh, cao - thấp là độ cao của âm thanh; GV lấy ví dụ hát nốt cao nhưng hát khẽ để HS thấy rõ.\n- GV cho HS chơi Bậc thang âm thanh: GV đọc thang âm Đô - Rê - Mi đi lên, HS đưa tay theo từng bậc, đọc đi xuống thì hạ tay theo.","hs":"- HS nghe và chỉ ra nốt nào cao hơn, làm động tác tay theo độ cao của âm.\n- HS mô phỏng tiếng chim hót cao, tiếng trống trường thấp, tiếng mèo kêu và tiếng bò kêu.\n- HS phân biệt được to - nhỏ khác với cao - thấp qua ví dụ của GV.\n- HS đưa tay theo từng bậc thang âm khi đọc Đô - Rê - Mi đi lên và đi xuống."},{"ten":"3. Luyện tập","gv":"- (12 phút) GV cho cả lớp hát ôn bài Lớp Một thân yêu theo nhạc đệm, nhắc HS lấy hơi ở cuối mỗi câu, hát rõ lời và không hét.\n- Chỗ HS hát chênh cao độ, GV đàn lại nốt đầu câu đó, hát mẫu chậm hai lần rồi cho HS hát nối câu sai với câu trước cho liền mạch.\n- GV cho HS luyện ba kiểu gõ đệm: gõ theo phách, gõ theo nhịp và gõ theo tiết tấu lời ca; mỗi kiểu thực hiện một lượt cả bài.\n- GV tổ chức chuỗi luyện tập: cả lớp, tổ (tổ hát - tổ gõ đệm rồi đổi vai), nhóm 4-6 HS, cuối cùng mời 2-3 HS xung phong hát cá nhân.\n- GV cho HS chơi trò hát nối tiếp theo tổ: tổ 1 hát câu 1, tổ 2 hát câu 2, tổ 3 hát câu 3, cả lớp hát câu cuối.","hs":"- HS hát ôn cả bài theo nhạc đệm, lấy hơi đúng chỗ và hát rõ lời.\n- HS hát lại câu còn chênh cao độ theo mẫu chậm của GV.\n- HS thực hiện đủ ba kiểu gõ đệm theo phách, theo nhịp và theo tiết tấu lời ca.\n- HS luyện tập theo cả lớp, theo tổ, theo nhóm 4-6 bạn và cá nhân xung phong.\n- HS hát nối tiếp theo tổ, vào đúng câu của tổ mình, không hát chồng lên nhau."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- (9 phút) GV chia nhóm 4-6 HS, giao nhiệm vụ nghĩ hai đến ba động tác phụ hoạ cho bài hát; GV gợi ý: hai tay nắm nhau đung đưa theo phách, tay chỉ về phía bạn bè khi hát đến tiếng bạn, hai tay vòng lên đầu như mái trường che chở.\n- GV cho các nhóm tập 3 phút rồi lần lượt lên biểu diễn theo tốp ca, một bạn gõ thanh phách đệm cho nhóm.\n- GV nêu tiêu chí nhận xét: thuộc lời, hát đúng giai điệu, hoà giọng, thể hiện được sắc thái to - nhỏ, động tác đều và tự tin.\n- GV củng cố chủ đề: Chủ đề 3 có tên là gì? Các em đã học bài hát nào, bài đọc nhạc nào? Âm thanh có thể cao - thấp, to - nhỏ, cho một ví dụ.\n- GV dặn HS về biểu diễn cho người thân xem và chuẩn bị đồ dùng cho chủ đề Vòng tay bạn bè.","hs":"- HS về nhóm bàn bạc và chọn động tác phụ hoạ phù hợp lời bài hát.\n- HS tập theo nhóm rồi lên biểu diễn, có bạn gõ thanh phách đệm.\n- HS nhận xét nhóm bạn theo tiêu chí GV nêu.\n- HS trả lời: chủ đề Mái trường thân yêu, bài Lớp Một thân yêu, bài đọc nhạc Ban nhạc Đô - Rê - Mi; tiếng chim hót cao, tiếng trống thấp.\n- HS ghi nhớ nhiệm vụ về nhà và đồ dùng cần chuẩn bị."}]},
{"lop":1,"mon":"Âm nhạc","tuan":14,"tiet":14,"bai":"Chủ đề 4: Vòng tay bạn bè — Học hát: Chào người bạn mới đến (Lương Bằng Vinh)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng giai điệu bài Chào người bạn mới đến.\n- Cảm nhận tính chất vui tươi, thân thiện của bài hát.\n2. Năng lực chung\n- Giao tiếp và hợp tác: hát hòa giọng cùng bạn.\n3. Phẩm chất\n- Nhân ái: yêu quý bạn bè, đoàn kết.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát cùng tên tác giả.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh tình bạn, thanh phách, thiết bị số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi trò chơi kết bạn, dẫn vào bài hát.","hs":"- HS tham gia trò chơi."},{"ten":"2. Khám phá — Học hát","gv":"- GV mở hát mẫu, đọc lời ca theo câu.\n- GV đàn và bắt nhịp cho HS tập hát từng câu đến hết bài.","hs":"- HS nghe mẫu, đọc lời, tập hát từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài, sửa sai, kết hợp vỗ tay theo nhịp.","hs":"- HS hát cả bài, vỗ tay theo nhịp."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cặp bạn hát; dặn HS hát cho bạn bè, gia đình nghe.","hs":"- HS biểu diễn, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Chào người bạn mới đến” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Lương Bằng Vinh”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Chào người bạn mới đến” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Chào người bạn mới đến” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Chào người bạn mới đến”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."}]},
{"lop":1,"mon":"Âm nhạc","tuan":15,"tiet":15,"bai":"Chủ đề 4: Vòng tay bạn bè — Ôn bài hát Chào người bạn mới đến; Nhạc cụ: Trống con","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu, kết hợp vận động phụ họa theo cặp/nhóm.\n- Nhận biết, gọi tên nhạc cụ trống con; biết cách gõ tạo âm thanh và gõ đệm theo bài hát.\n2. Năng lực chung\n- Giao tiếp và hợp tác: phối hợp biểu diễn, gõ đệm cùng bạn.\n3. Phẩm chất\n- Nhân ái, đoàn kết, chăm chỉ luyện tập.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS cầm và gõ được nhạc cụ Trống con đúng cách sau khi xem phim cận cảnh.","dodung":"- GV: trống con (hoặc hộp thiếc bịt vải làm trống thay thế), đàn phím điện tử hoặc file nhạc đệm, loa, tranh nhạc cụ gõ, thanh phách, máy chiếu/tivi.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV bắt nhịp cho cả lớp hát bài Chào người bạn mới đến kết hợp vỗ tay theo phách, nhắc HS lấy hơi ở cuối mỗi câu hát.\n- GV cho HS hát lần hai theo hình thức đối đáp: tổ 1 hát câu 1, tổ 2 hát câu 2, cả lớp hát câu cuối.\n- GV hỏi: Khi có bạn mới đến lớp, em sẽ nói gì và làm gì với bạn?\n- GV dẫn vào bài: hôm nay lớp mình làm quen thêm một nhạc cụ gõ mới là trống con.","hs":"- HS hát cả bài kết hợp vỗ tay theo phách, lấy hơi đúng chỗ.\n- HS hát đối đáp theo tổ, vào đúng câu của tổ mình.\n- HS trả lời: em chào bạn, mời bạn cùng chơi, cho bạn mượn đồ dùng.\n- HS lắng nghe, nhắc lại tên nhạc cụ sắp học."},{"ten":"2. Khám phá — Giới thiệu trống con","gv":"- (9 phút) GV đưa trống con cho HS quan sát: mặt trống tròn căng, thân trống bằng gỗ, có dùi trống; tiếng trống nghe tùng tùng, vang và ấm hơn tiếng thanh phách.\n- GV làm mẫu tư thế: đặt trống trên bàn hoặc kẹp nhẹ giữa hai đầu gối, tay thuận cầm dùi ở khoảng giữa cán, cổ tay mềm, gõ vào giữa mặt trống rồi nhấc dùi lên ngay cho tiếng vang.\n- GV gõ mẫu chậm hai lần, sau đó gõ theo tiếng đếm 1-2, 1-2 để HS nghe tiếng đều.\n- GV nêu lỗi HS hay mắc và cách sửa: cầm dùi quá sát đầu làm tiếng bí thì chỉnh lại tay; đập quá mạnh làm tiếng chát thì gõ vừa lực; để dùi tì lên mặt trống làm tiếng cụt thì nhắc nhấc dùi lên ngay sau khi gõ.","hs":"- HS quan sát trống con và nói được: mặt trống tròn, có dùi, tiếng nghe tùng tùng, vang hơn thanh phách.\n- HS đặt trống và cầm dùi theo đúng mẫu của GV, gõ thử vài tiếng.\n- HS gõ theo tiếng đếm của GV cho tiếng đều nhau.\n- HS nhận ra lỗi cầm dùi sai, gõ quá mạnh và sửa lại theo hướng dẫn."},{"ten":"3. Luyện tập — Gõ đệm","gv":"- (10 phút) GV cho HS gõ trống con theo tiếng đếm 1-2 khoảng một phút cho quen tay, yêu cầu gõ vừa lực và đều.\n- GV hát bài Chào người bạn mới đến thật chậm, gõ mẫu theo phách để HS nghe rõ tiếng gõ rơi vào tiếng hát nào.\n- GV cho HS vừa hát vừa gõ đệm theo phách cả bài, sau đó đổi sang gõ theo nhịp (chỉ gõ vào phách mạnh) để HS so sánh hai cách.\n- GV sửa sai: nhóm gõ nhanh dần thì GV đếm to giữ nhịp; bạn gõ lệch phách thì GV gõ cùng vài nhịp rồi buông ra cho HS tự giữ nhịp.","hs":"- HS gõ trống con theo tiếng đếm, giữ lực gõ vừa phải và đều.\n- HS nghe mẫu và nhận ra tiếng hát nào cần gõ vào.\n- HS vừa hát vừa gõ đệm theo phách, sau đó gõ theo nhịp.\n- HS gõ chậm lại theo tiếng đếm của GV khi bị nhanh dần."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV chia lớp thành 3 tổ luân phiên: tổ 1 hát, tổ 2 gõ trống con theo phách, tổ 3 gõ thanh phách theo tiết tấu lời ca, sau mỗi lượt thì đổi vai.\n- GV mời 2-3 nhóm 4-6 HS lên biểu diễn vừa hát vừa gõ đệm, kết hợp vận động theo cặp: hai bạn nắm tay nhau đung đưa theo phách rồi bắt tay chào nhau ở câu cuối.\n- GV nêu tiêu chí nhận xét: cầm dùi và gõ trống đúng cách, gõ đúng phách, hát hoà giọng, phối hợp nhịp nhàng với bạn, mạnh dạn tự tin.\n- GV dặn HS giữ gìn nhạc cụ, về nhà tập gõ đệm cho bài hát và chuẩn bị đồ dùng cho tiết sau.","hs":"- HS thực hiện theo tổ và đổi vai hát, gõ trống con, gõ thanh phách.\n- HS lên biểu diễn theo nhóm, kết hợp vận động theo cặp cùng bạn.\n- HS nhận xét bạn theo tiêu chí GV nêu.\n- HS ghi nhớ việc luyện tập ở nhà và giữ gìn nhạc cụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu đoạn phim quay cận cảnh nhạc cụ Trống con: nhìn rõ hình dáng, chất liệu, cách cầm và cách gõ sao cho ra đúng tiếng; GV tua chậm đúng động tác khó, cho xem lại hai ba lần rồi mới phát nhạc cụ thật để HS làm theo.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV thu âm tiếng gõ Trống con của từng tổ rồi mở lại cho cả lớp nghe; HS nghe ra tổ nào gõ đều, tổ nào còn lúc nhanh lúc chậm — nghe lại bản thu giúp HS nhận ra điều mà lúc đang gõ không nhận ra được.\n⚠ (Miền 4: An toàn) Cầm Trống con đúng cách, gõ vừa lực, không đập mạnh xuống bàn và không chĩa vào người bạn; GV thao tác máy chiếu và điện thoại, HS không tự cầm thiết bị; bản thu tiếng gõ của lớp chỉ mở trong giờ học, không gửi ra ngoài lớp.","hs":"- HS cầm và gõ được nhạc cụ Trống con đúng cách sau khi xem phim cận cảnh.\n- HS nghe lại bản thu tiếng gõ của tổ và chỉ ra chỗ gõ chưa đều."}]},
{"lop":1,"mon":"Âm nhạc","tuan":16,"tiet":16,"bai":"Chủ đề 4: Vòng tay bạn bè — Thường thức âm nhạc: Trống cái; Nghe nhạc: Vũ khúc thiên nga (Trai-cốp-xki)","yccd":"1. Năng lực âm nhạc\n- Nhận biết nhạc cụ trống cái; cảm nhận âm thanh vang, trầm của trống cái.\n- Lắng nghe và cảm nhận giai điệu nhẹ nhàng, uyển chuyển của Vũ khúc thiên nga; biết vận động theo nhạc.\n2. Năng lực chung\n- Tự chủ: mạnh dạn nêu cảm nhận.\n3. Phẩm chất\n- Yêu âm nhạc, yêu cái đẹp.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS nêu được đặc điểm nổi bật của “Trống cái” nhờ quan sát tư liệu số và nghe bản thu.","dodung":"- Giáo viên: loa, file nhạc, hình ảnh/video trống cái và múa thiên nga, thiết bị mở học liệu số.\n- Học sinh: SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS nghe âm thanh một tiếng trống cái, hỏi cảm nhận âm thanh to hay nhỏ, vang hay không.","hs":"- HS nghe, nêu cảm nhận."},{"ten":"2. Khám phá — Trống cái và nghe nhạc","gv":"- GV giới thiệu trống cái: hình dáng lớn, âm thanh vang, trầm.\n- GV mở trích đoạn Vũ khúc thiên nga cho HS nghe; hỏi cảm nhận: nhẹ nhàng hay mạnh mẽ.","hs":"- HS nghe giới thiệu trống cái; lắng nghe bài nghe nhạc và nêu cảm nhận."},{"ten":"3. Luyện tập — Vận động theo nhạc","gv":"- GV hướng dẫn HS vận động cơ thể nhẹ nhàng theo giai điệu (dang tay như cánh thiên nga).","hs":"- HS vận động theo nhạc."},{"ten":"4. Vận dụng","gv":"- GV cho HS nghe lại và mời vài HS biểu diễn động tác tự nghĩ.","hs":"- HS biểu diễn động tác sáng tạo."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu đoạn phim quay cận cảnh cho nội dung “Trống cái”: nhìn rõ hình dáng, chất liệu, số dây hoặc số lỗ, bàn tay nghệ sĩ đặt ở đâu và làm động tác gì để ra tiếng; GV tua chậm và dừng đúng chỗ đó — chi tiết này tranh in trong sách và một lần nghe trên lớp không cho thấy được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) HS làm bài tập nghe tương tác có chấm ngay: GV mở lần lượt vài đoạn nhạc ngắn, HS chọn đoạn nào có âm sắc của nhạc cụ vừa học trong “Trống cái”; chọn sai thì nghe lại đoạn đó và chọn lần nữa cho tới khi nhận ra đúng.\n⚠ (Miền 4: An toàn) Tư liệu về “Trống cái” phải lấy từ trang của nhà xuất bản, nhà hát, bảo tàng hoặc kênh chính thức của nghệ sĩ và tải sẵn về máy trước giờ lên lớp để không lẫn quảng cáo; khi kể lại cho người khác phải nói rõ mình đã xem ở đâu, không nhận tư liệu của người khác là của mình; mở âm lượng vừa đủ nghe.","hs":"- HS nêu được đặc điểm nổi bật của “Trống cái” nhờ quan sát tư liệu số và nghe bản thu.\n- HS làm bài tập tương tác, nhận ra âm sắc – nội dung đã học và tự sửa khi chọn sai."}]},
{"lop":1,"mon":"Âm nhạc","tuan":17,"tiet":17,"bai":"Chủ đề 4: Vòng tay bạn bè — Vận dụng — Sáng tạo; Ôn tập chủ đề 4","yccd":"1. Năng lực âm nhạc\n- Hát thuộc và biểu diễn bài Chào người bạn mới đến kết hợp vận động, gõ đệm.\n- Củng cố kĩ năng gõ trống con và cảm nhận âm sắc nhạc cụ.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: nghĩ động tác, cách gõ mới.\n3. Phẩm chất\n- Nhân ái, đoàn kết, tự tin thể hiện.","dodung":"- GV: đàn phím điện tử hoặc file nhạc đệm, loa, trống con, thanh phách, tranh minh hoạ tình bạn, máy chiếu/tivi để mở học liệu số.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV cho HS chơi trò Gõ tiết tấu đối đáp: GV gõ một mẫu tiết tấu ngắn bốn tiếng bằng thanh phách, cả lớp gõ lại đúng như vậy; GV tăng dần độ khó bằng mẫu có tiếng dài, tiếng ngắn xen kẽ.\n- GV chia lớp thành hai nhóm chơi đối đáp: nhóm 1 gõ một mẫu tự nghĩ, nhóm 2 nghe và gõ lại cho đúng, sau đó đổi vai.\n- GV hỏi: Nhóm bạn gõ nhanh hay chậm? Có tiếng nào ngân dài hơn các tiếng khác không?\n- GV dẫn vào bài: tiết này lớp mình ôn tập chủ đề Vòng tay bạn bè và sáng tạo cách biểu diễn.","hs":"- HS nghe và gõ lại đúng mẫu tiết tấu GV vừa gõ.\n- HS chơi đối đáp theo nhóm, nghe kĩ rồi gõ lại mẫu của nhóm bạn.\n- HS trả lời theo cảm nhận về tốc độ và độ dài các tiếng gõ.\n- HS lắng nghe, nhắc lại nội dung tiết học."},{"ten":"2. Khám phá","gv":"- (7 phút) GV cùng HS nhắc lại chủ đề 4 qua ba câu hỏi: Chủ đề 4 có tên là gì? Các em đã học bài hát nào? Đã làm quen nhạc cụ gõ nào mới?\n- GV cho HS nhắc lại cách cầm dùi và gõ trống con, mỗi tổ cử một bạn lên làm mẫu cho cả lớp xem và nhận xét.\n- GV cho HS so sánh âm sắc: tiếng thanh phách khô và gọn, tiếng trống con vang và ấm; GV gõ lần lượt hai nhạc cụ, HS nhắm mắt nghe và đoán đó là nhạc cụ nào.\n- GV chốt: chủ đề Vòng tay bạn bè nhắc các em biết yêu thương, đoàn kết và cùng nhau chơi, cùng nhau hát.","hs":"- HS nhắc lại: chủ đề Vòng tay bạn bè, bài hát Chào người bạn mới đến, nhạc cụ trống con.\n- HS lên làm mẫu cách cầm dùi và gõ trống con, nhận xét bạn làm đúng hay chưa đúng.\n- HS nhắm mắt nghe và đoán đúng tên nhạc cụ vừa vang lên.\n- HS lắng nghe và nhắc lại ý nghĩa của chủ đề."},{"ten":"3. Luyện tập","gv":"- (12 phút) GV cho cả lớp hát ôn bài Chào người bạn mới đến theo nhạc đệm, nhắc HS lấy hơi ở cuối mỗi câu, hát rõ lời, giọng vui tươi và thân thiện.\n- Chỗ HS hát chênh cao độ, GV đàn lại nốt đầu của câu đó, hát mẫu chậm hai lần rồi cho HS hát nối câu sai với câu trước cho liền mạch.\n- GV cho HS luyện đủ ba kiểu gõ đệm: gõ theo phách, gõ theo nhịp và gõ theo tiết tấu lời ca, mỗi kiểu một lượt cả bài.\n- GV tổ chức chuỗi luyện tập: cả lớp hát, luyện theo tổ (tổ hát - tổ gõ đệm rồi đổi vai), luyện theo cặp hai bạn quay mặt vào nhau, nhóm 4-6 HS, cuối cùng cá nhân xung phong.\n- GV cho HS chơi trò hát to - hát thầm theo hiệu lệnh tay của GV để rèn giữ nhịp.","hs":"- HS hát ôn cả bài theo nhạc đệm, lấy hơi đúng chỗ, hát rõ lời với giọng vui tươi.\n- HS hát lại câu còn chênh cao độ theo mẫu chậm của GV.\n- HS thực hiện ba kiểu gõ đệm theo phách, theo nhịp và theo tiết tấu lời ca.\n- HS luyện tập theo cả lớp, theo tổ, theo cặp, theo nhóm 4-6 bạn và cá nhân.\n- HS chơi hát to - hát thầm, vẫn giữ đúng nhịp khi hát thầm."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- (11 phút) GV chia nhóm 4-6 HS, giao hai nhiệm vụ sáng tạo: nghĩ hai động tác phụ hoạ và nghĩ một cách gõ đệm mới; GV gợi ý động tác bắt tay chào bạn, khoác vai đung đưa theo phách, vòng tay thành vòng tròn ở câu cuối.\n- GV gợi ý cách gõ mới: vỗ tay hai tiếng rồi vỗ vào vai bạn một tiếng, hoặc gõ thanh phách một tiếng rồi gõ trống con một tiếng luân phiên.\n- GV cho các nhóm tập 3 phút rồi lần lượt lên biểu diễn; cả lớp vỗ tay theo phách cổ vũ.\n- GV nêu tiêu chí nhận xét: thuộc lời, hát đúng giai điệu, hoà giọng, gõ đệm đúng phách, phối hợp nhịp nhàng, mạnh dạn tự tin.\n- GV củng cố và dặn HS ôn lại tất cả bài hát đã học trong học kì để chuẩn bị cho tiết ôn tập, đánh giá cuối học kì I.","hs":"- HS về nhóm bàn bạc, chọn động tác phụ hoạ và cách gõ đệm mới cho nhóm mình.\n- HS thử nghiệm cách gõ mới, tập cho đều và khớp với lời bài hát.\n- HS lên biểu diễn trước lớp, các bạn ở dưới vỗ tay theo phách cổ vũ.\n- HS nhận xét nhóm bạn theo tiêu chí GV nêu.\n- HS ghi nhớ nhiệm vụ ôn tập ở nhà chuẩn bị cho tiết đánh giá cuối học kì."}]},
{"lop":1,"mon":"Âm nhạc","tuan":18,"tiet":18,"bai":"Ôn tập và đánh giá cuối học kì I","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu các bài hát đã học trong học kì I; biết gõ đệm và vận động phù hợp.\n- Nhận biết một số nhạc cụ gõ (thanh phách, trống con) và ba nốt Đô-Rê-Mi.\n2. Năng lực chung\n- Tự chủ và tự học: tự đánh giá kết quả học tập của bản thân.\n3. Phẩm chất\n- Chăm chỉ, tự tin biểu diễn.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS trả lời đúng bộ câu hỏi ôn tập và gọi được tên bài hát, tên tác giả đã học.","dodung":"- GV: đàn phím điện tử hoặc file nhạc đệm các bài đã học, loa, thanh phách, trống con, thăm ghi tên bài hát và hình thức biểu diễn, phiếu đánh giá, máy chiếu/tivi.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS chơi Nghe giai điệu đoán tên bài hát: GV đàn câu mở đầu của bốn bài đã học trong học kì I, mỗi câu một lần, HS giơ tay đoán.\n- GV nâng độ khó bằng cách chỉ gõ tiết tấu lời ca một câu hát, HS nghe tiết tấu và đoán tên bài.\n- GV cho cả lớp hát lại một bài mà nhiều HS yêu thích để tạo không khí vui vẻ trước khi ôn tập.\n- GV nêu nhiệm vụ tiết học: ôn lại và biểu diễn các nội dung đã học, tự nhận xét sự tiến bộ của mình.","hs":"- HS lắng nghe và đoán đúng tên các bài hát đã học.\n- HS nghe tiết tấu gõ và đoán được câu hát tương ứng.\n- HS hát lại một bài yêu thích cùng cả lớp.\n- HS lắng nghe, nhắc lại nhiệm vụ của tiết ôn tập."},{"ten":"2. Khám phá — Hệ thống","gv":"- (7 phút) GV cùng HS hệ thống lại theo bốn chủ đề: chủ đề 1 bài Vào rừng hoa và âm to - nhỏ, dài - ngắn; chủ đề 2 bài Lá cờ Việt Nam và thanh phách; chủ đề 3 bài Lớp Một thân yêu, bài đọc nhạc Ban nhạc Đô - Rê - Mi; chủ đề 4 bài Chào người bạn mới đến và trống con.\n- GV đưa lần lượt thanh phách và trống con, HS gọi tên nhạc cụ, nói cách cầm và gõ đúng.\n- GV cho HS đọc lại ba nốt Đô - Rê - Mi theo kí hiệu bàn tay, đọc thang âm đi lên rồi đi xuống.\n- GV thông báo trước hình thức đánh giá và các tiêu chí để HS chuẩn bị tinh thần.","hs":"- HS nhắc lại tên các chủ đề, bài hát, bài đọc nhạc và nhạc cụ đã học.\n- HS gọi đúng tên nhạc cụ, làm lại cách cầm và gõ cho cả lớp xem.\n- HS đọc ba nốt Đô - Rê - Mi theo kí hiệu bàn tay, đọc thang âm hai chiều.\n- HS lắng nghe và ghi nhớ các tiêu chí đánh giá."},{"ten":"3. Luyện tập — Đánh giá","gv":"- (13 phút) GV cho các nhóm 4-6 HS bốc thăm: trong thăm ghi tên bài hát và hình thức trình bày (hát kết hợp gõ đệm theo phách, hát kết hợp vận động phụ hoạ, hoặc hát nối tiếp theo tổ).\n- GV cho các nhóm chuẩn bị 3 phút, nhắc HS phân công bạn hát chính, bạn gõ đệm và đứng thành hàng ngay ngắn.\n- GV nêu rõ năm tiêu chí đánh giá: thuộc lời, hát đúng giai điệu, hoà giọng cùng nhóm, gõ đệm đúng phách, mạnh dạn tự tin.\n- Các nhóm lần lượt biểu diễn; GV ghi nhận vào phiếu đánh giá theo mức hoàn thành tốt, hoàn thành, cần cố gắng, chú trọng sự tiến bộ so với đầu năm.\n- GV mời một vài HS xung phong biểu diễn cá nhân hoặc đọc bài đọc nhạc kết hợp kí hiệu bàn tay.","hs":"- HS bốc thăm theo nhóm và nhận nhiệm vụ biểu diễn.\n- HS chuẩn bị trong nhóm, phân công bạn hát chính, bạn gõ đệm, đứng thành hàng ngay ngắn.\n- HS ghi nhớ năm tiêu chí đánh giá trước khi lên biểu diễn.\n- HS biểu diễn trước lớp, tự nhận xét nhóm mình và nhận xét nhóm bạn.\n- Một số HS xung phong biểu diễn cá nhân hoặc đọc bài đọc nhạc."},{"ten":"4. Vận dụng","gv":"- (6 phút) GV công bố nhận xét chung, khen cụ thể từng nhóm một điểm mạnh và gợi ý một điều cần luyện thêm trong học kì II.\n- GV cho cả lớp cùng hát một bài yêu thích nhất kết hợp gõ đệm và vận động để kết thúc học kì trong không khí vui tươi.\n- GV hỏi để HS tự đánh giá: Trong học kì này em thích nhất bài hát nào? Em thấy mình tiến bộ ở điều gì?\n- GV dặn HS trong kì nghỉ vẫn hát cho người thân nghe, giữ gìn nhạc cụ gõ và chuẩn bị SGK, thanh phách cho chủ đề Nhịp điệu mùa xuân của học kì II.","hs":"- HS lắng nghe nhận xét, ghi nhớ điều cần luyện thêm.\n- HS cùng cả lớp hát bài yêu thích kết hợp gõ đệm và vận động.\n- HS tự đánh giá, nói được bài hát mình thích và điều mình đã tiến bộ.\n- HS ghi nhớ nhiệm vụ trong kì nghỉ và đồ dùng cần chuẩn bị."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại quay lại phần biểu diễn học kì I của từng tổ rồi mở ngay lên màn hình cho cả lớp cùng xem; HS nhận ra tổ mình đã đứng ngay ngắn chưa, vào bài có đều không, hát đã rõ lời chưa — xem lại chính mình là điều biểu diễn xong rồi kể lại không làm được.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV cho HS làm bộ câu hỏi tương tác có chấm ngay để ôn lại học kì I: nghe một đoạn nhạc rồi chọn đúng tên bài hát, nối tên nhạc cụ với hình, chọn đúng tên tác giả bài hát; sai câu nào GV mở lại đúng đoạn nhạc của câu đó cho HS nghe lại.\n⚠ (Miền 4: An toàn) Đoạn phim quay lớp chỉ mở trong giờ học và trong buổi họp phụ huynh khi cả lớp đồng ý, không đăng lên mạng, không gửi cho người ngoài; bạn nào không muốn bị quay thì GV không quay; nhận xét bạn bằng lời tử tế, không chê bai hình dáng hay giọng hát của bạn.","hs":"- HS xem lại đoạn phim phần biểu diễn của tổ và chỉ ra được một chỗ cần sửa.\n- HS trả lời đúng bộ câu hỏi ôn tập và gọi được tên bài hát, tên tác giả đã học."}]},
{"lop":1,"mon":"Âm nhạc","tuan":19,"tiet":19,"bai":"Chủ đề 5: Nhịp điệu mùa xuân — Học hát: Xúc xắc xúc xẻ (Dân gian Việt Nam)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng giai điệu bài Xúc xắc xúc xẻ.\n- Cảm nhận không khí vui tươi, rộn ràng của mùa xuân qua bài hát.\n- Biết hát kết hợp vận động cơ thể theo nhịp.\n2. Năng lực chung\n- Giao tiếp và hợp tác: hát hòa giọng cùng bạn.\n3. Phẩm chất\n- Yêu truyền thống, yêu không khí mùa xuân.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát cùng tên tác giả.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh cảnh mùa xuân/ngày Tết, thanh phách, thiết bị số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV hỏi HS về mùa xuân, ngày Tết (hoa gì nở, có gì vui), dẫn vào bài.","hs":"- HS trả lời, chia sẻ."},{"ten":"2. Khám phá — Học hát","gv":"- GV mở hát mẫu, đọc lời ca theo câu.\n- GV đàn và bắt nhịp cho HS tập hát từng câu đến hết bài.","hs":"- HS nghe mẫu, đọc lời, tập hát từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài, sửa sai, kết hợp vỗ tay và vận động cơ thể theo nhịp.","hs":"- HS hát cả bài, vỗ tay và vận động theo nhịp."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cá nhân hát; dặn HS hát cho gia đình nghe dịp xuân.","hs":"- HS biểu diễn, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Xúc xắc xúc xẻ” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Dân gian Việt Nam”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Xúc xắc xúc xẻ” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Xúc xắc xúc xẻ” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Xúc xắc xúc xẻ”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."}]},
{"lop":1,"mon":"Âm nhạc","tuan":20,"tiet":20,"bai":"Chủ đề 5: Nhịp điệu mùa xuân — Ôn bài hát Xúc xắc xúc xẻ; Nghe nhạc: Khát vọng mùa xuân (Nhạc: Mô-da; phỏng dịch lời: Tô Hải)","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu Xúc xắc xúc xẻ, kết hợp vận động cơ thể theo nhịp điệu bài hát.\n- Lắng nghe và cảm nhận tính chất trong sáng, nhẹ nhàng, bức tranh mùa xuân yên bình trong bài Khát vọng mùa xuân của Mô-da.\n- Biết hát theo hình thức tốp ca, song ca, cá nhân.\n2. Năng lực chung\n- Giao tiếp và hợp tác: phối hợp biểu diễn.\n3. Phẩm chất\n- Chăm chỉ, tự tin, yêu mùa xuân.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên tác phẩm và tên tác giả có ghi trong phần chú thích.","dodung":"- Giáo viên: đàn/file nhạc, loa, thanh phách, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS hát lại bài Xúc xắc xúc xẻ.","hs":"- HS hát tập thể."},{"ten":"2. Khám phá — Nghe nhạc Khát vọng mùa xuân","gv":"- GV mở bài Khát vọng mùa xuân (Nhạc: Mô-da; phỏng dịch lời: Tô Hải) cho HS nghe; hỏi cảm nhận: nhẹ nhàng hay sôi động, gợi hình ảnh gì về mùa xuân.\n- GV làm mẫu vài động tác vận động cơ thể theo nhịp điệu; hướng dẫn HS.","hs":"- HS lắng nghe, nêu cảm nhận và vận động nhẹ nhàng theo nhạc."},{"ten":"3. Luyện tập","gv":"- GV cho HS ôn hát Xúc xắc xúc xẻ kết hợp vận động theo dãy/tổ; hát tốp ca, song ca.","hs":"- HS ôn hát và vận động theo nhiều hình thức."},{"ten":"4. Vận dụng","gv":"- GV cho nhóm luân phiên biểu diễn, nhận xét, tuyên dương.","hs":"- HS biểu diễn, nhận xét."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản ghi hình buổi biểu diễn tác phẩm “Khát vọng mùa xuân” (Nhạc: Mô-da; phỏng dịch lời: Tô Hải) để HS vừa nghe vừa nhìn thấy người nghệ sĩ đang chơi nhạc cụ nào, ngồi và cầm đàn ra sao; GV tạm dừng đúng lúc để HS chỉ lên màn hình gọi tên nhạc cụ vừa vang lên.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV cho HS đọc phần chú thích dưới đoạn phim: tên tác phẩm, tên tác giả, tên người biểu diễn; HS hiểu bản nhạc nào cũng do một người viết ra, nhắc đến bản nhạc thì phải gọi đúng tên người ấy.\n⚠ (Miền 4: An toàn) GV chọn và tải sẵn đoạn phim về “Khát vọng mùa xuân” trước giờ học rồi mở ngoại tuyến để HS không nhìn thấy quảng cáo và các đoạn phim gợi ý bên cạnh; âm lượng để vừa nghe, HS ngồi cách màn hình vừa tầm mắt và không tự thao tác thiết bị.","hs":"- HS nghe và xem bản ghi hình “Khát vọng mùa xuân”, gọi được tên nhạc cụ đang vang lên trên màn hình.\n- HS nói được tên tác phẩm và tên tác giả có ghi trong phần chú thích."}]},
{"lop":1,"mon":"Âm nhạc","tuan":21,"tiet":21,"bai":"Chủ đề 5: Nhịp điệu mùa xuân — Đọc nhạc: Những người bạn của Đô — Rê — Mi","yccd":"1. Năng lực âm nhạc\n- Nhận biết và ghi nhớ thêm hai nốt Pha, Son (bên cạnh Đô, Rê, Mi).\n- Đọc được bài Những người bạn của Đô — Rê — Mi theo kí hiệu bàn tay.\n2. Năng lực chung\n- Tự chủ và tự học: tự luyện đọc nốt.\n3. Phẩm chất\n- Chăm chỉ luyện tập.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS đọc đúng cao độ “Những người bạn của Đô — Rê — Mi” nhờ nghe mẫu từ đàn phím.","dodung":"- GV: đàn phím điện tử, loa, tranh kí hiệu bàn tay năm nốt Đô - Rê - Mi - Pha - Son, bảng phụ chép bài đọc nhạc, thanh phách, máy chiếu/tivi.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV đàn ba nốt Đô - Rê - Mi rồi làm kí hiệu bàn tay, cả lớp đọc theo thang âm đi lên và đi xuống, mỗi chiều hai lần.\n- GV chơi trò đố nhanh: GV làm một kí hiệu bàn tay bất kì trong ba nốt đã học, HS đọc ngay tên nốt và đọc đúng cao độ.\n- GV hỏi: Trong ba nốt vừa đọc, nốt nào cao nhất, nốt nào thấp nhất?\n- GV dẫn vào bài: hôm nay ba bạn Đô - Rê - Mi có thêm hai người bạn mới.","hs":"- HS đọc thang âm Đô - Rê - Mi đi lên, đi xuống theo tay GV.\n- HS nhìn kí hiệu bàn tay và đọc ngay tên nốt, đọc đúng cao độ.\n- HS trả lời: nốt Mi cao nhất, nốt Đô thấp nhất.\n- HS lắng nghe, tò mò chờ làm quen hai nốt mới."},{"ten":"2. Khám phá — Làm quen Pha, Son","gv":"- (10 phút) GV giới thiệu hai nốt mới: sau Mi là nốt Pha, sau Pha là nốt Son; GV đàn từng nốt cho HS nghe rõ cao độ, mỗi nốt đàn hai lần.\n- GV làm mẫu kí hiệu bàn tay: nốt Pha bàn tay nắm hờ, ngón cái chỉ xuống; nốt Son bàn tay để thẳng đứng; GV nhấn mạnh tay đưa càng cao thì nốt càng cao.\n- GV cho cả lớp đọc thang âm năm nốt đi lên Đô - Rê - Mi - Pha - Son và đi xuống Son - Pha - Mi - Rê - Đô, đọc chậm và giữ hơi đều.\n- GV đàn hai nốt bất kì trong năm nốt, HS nghe và nói nốt sau cao hơn hay thấp hơn nốt trước.","hs":"- HS nghe cao độ hai nốt Pha, Son và đọc theo mẫu của GV.\n- HS làm đúng kí hiệu bàn tay cho nốt Pha và nốt Son.\n- HS đọc thang âm năm nốt đi lên và đi xuống, giữ hơi đều.\n- HS nghe và so sánh được nốt nào cao hơn, nốt nào thấp hơn."},{"ten":"3. Luyện tập","gv":"- (12 phút) GV treo bảng phụ bài Những người bạn của Đô - Rê - Mi, chỉ rõ bài có bốn câu ngắn; GV đàn lấy cao độ rồi đọc mẫu cả bài kết hợp kí hiệu bàn tay.\n- GV dạy theo lối móc xích: đọc mẫu câu 1 hai lần rồi bắt nhịp cho HS đọc lại, làm tương tự câu 2 rồi ghép câu 1 với câu 2; dạy tiếp câu 3, câu 4 rồi ghép cả bài.\n- GV sửa sai: chỗ HS đọc chênh cao độ, GV đàn lại nốt đầu câu đó, đọc mẫu thật chậm rồi cho HS đọc nối câu sai với câu đứng trước.\n- GV cho HS đọc cả bài kết hợp gõ phách bằng thanh phách, nhắc gõ đều tay và nhẹ hơn tiếng đọc.\n- GV luyện theo chuỗi: cả lớp, tổ (tổ đọc - tổ gõ phách rồi đổi vai), nhóm 4-6 HS, cuối cùng cá nhân xung phong.","hs":"- HS quan sát bảng phụ, đếm được bốn câu và nghe GV đọc mẫu.\n- HS đọc từng câu theo lối móc xích, ghép hai câu rồi ghép cả bài.\n- HS đọc lại câu còn chênh cao độ theo mẫu chậm của GV.\n- HS đọc cả bài kết hợp gõ phách đều tay.\n- HS luyện đọc theo cả lớp, theo tổ, theo nhóm 4-6 bạn và cá nhân."},{"ten":"4. Vận dụng","gv":"- (5 phút) GV tổ chức trò chơi Năm người bạn: mỗi tổ nhận một nốt, GV chỉ vào tổ nào thì tổ đó đọc vang tên nốt của mình đúng cao độ, GV chỉ nhanh dần để tạo hứng thú.\n- GV mời 2-3 nhóm hoặc cá nhân đọc lại cả bài kết hợp làm kí hiệu bàn tay trước lớp.\n- GV nêu tiêu chí nhận xét: đọc đúng cao độ năm nốt, đọc đều nhịp, làm kí hiệu bàn tay đúng, mạnh dạn tự tin.\n- GV dặn HS về đọc lại bài cho người thân nghe, tập làm kí hiệu bàn tay và chuẩn bị đồ dùng cho tiết ôn tập chủ đề 5.","hs":"- HS chơi trò Năm người bạn, đọc đúng cao độ nốt của tổ mình khi GV chỉ.\n- HS đọc lại cả bài kết hợp kí hiệu bàn tay theo nhóm hoặc cá nhân.\n- HS nhận xét bạn theo tiêu chí GV nêu.\n- HS ghi nhớ nhiệm vụ về nhà và đồ dùng cần chuẩn bị."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV dùng đàn phím điện tử hoặc phần mềm đàn phím trên máy tính để lấy cao độ chuẩn cho “Những người bạn của Đô — Rê — Mi”: bấm từng nốt cho HS nghe rõ, bấm chậm cả câu, rồi bấm lại đúng nốt mà HS còn đọc chênh — cao độ lấy từ đàn chuẩn hơn lấy từ giọng người vì không bị lệch theo hơi thở.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở trò chơi nghe nốt trên máy: máy phát một nốt, HS giơ kí hiệu bàn tay tương ứng, GV bấm lại nốt đó để cả lớp cùng kiểm tra ngay đúng hay sai rồi đọc lại — HS biết mình sai ở nốt nào ngay tại chỗ chứ không chờ hết giờ.\n⚠ (Miền 4: An toàn) GV thao tác đàn và máy tính, HS chỉ nghe và đọc theo, không tự bấm vào thiết bị của GV; mở âm lượng vừa đủ nghe để không hại tai; chỉ dùng phần mềm GV đã cài sẵn, không mở phần mềm hay trang khác trong giờ học.","hs":"- HS đọc đúng cao độ “Những người bạn của Đô — Rê — Mi” nhờ nghe mẫu từ đàn phím.\n- HS nhận ra ngay nốt mình đọc còn chênh và đọc lại cho đúng."}]},
{"lop":1,"mon":"Âm nhạc","tuan":22,"tiet":22,"bai":"Chủ đề 5: Nhịp điệu mùa xuân — Vận dụng — Sáng tạo; Ôn tập chủ đề 5","yccd":"1. Năng lực âm nhạc\n- Hát thuộc và biểu diễn bài Xúc xắc xúc xẻ kết hợp vận động, gõ đệm.\n- Củng cố đọc nhạc 5 nốt và cảm nhận nhịp điệu mùa xuân.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: nghĩ động tác phụ họa.\n3. Phẩm chất\n- Yêu mùa xuân, tự tin thể hiện.","dodung":"- GV: đàn phím điện tử hoặc file nhạc đệm bài Xúc xắc xúc xẻ, loa, thanh phách, trống con, tranh cảnh mùa xuân, máy chiếu/tivi để mở học liệu số.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV mở một đoạn nhạc mùa xuân vui tươi và cho HS chơi trò Vận động theo nhạc: khi nhạc vang lên thì HS đứng tại chỗ nhún chân, vỗ tay theo nhịp; khi nhạc dừng thì HS đứng im như tượng.\n- GV đổi hiệu lệnh: nhạc nhanh thì vỗ tay nhanh, nhạc chậm thì vỗ tay chậm, giúp HS cảm nhận tốc độ.\n- GV hỏi: Đoạn nhạc vừa nghe vui hay buồn? Mùa xuân đến, nhà em thường làm gì?\n- GV dẫn vào bài: tiết này lớp mình ôn tập chủ đề Nhịp điệu mùa xuân và sáng tạo cách biểu diễn.","hs":"- HS vận động theo nhạc, dừng lại đứng im khi nhạc tắt.\n- HS vỗ tay nhanh hoặc chậm đúng theo tốc độ của nhạc.\n- HS trả lời: đoạn nhạc vui tươi, rộn ràng; nhà em gói bánh, đi chúc Tết.\n- HS lắng nghe, nhắc lại nội dung tiết học."},{"ten":"2. Khám phá","gv":"- (7 phút) GV cùng HS nhắc lại chủ đề 5 qua ba câu hỏi: Chủ đề 5 có tên là gì? Các em học bài hát nào? Bài đọc nhạc có mấy nốt, kể tên các nốt đó.\n- GV cho HS đọc lại thang âm năm nốt Đô - Rê - Mi - Pha - Son đi lên rồi đi xuống, kết hợp kí hiệu bàn tay.\n- GV hỏi thêm về nội dung bài hát: Bài Xúc xắc xúc xẻ nhắc đến phong tục gì của trẻ em vào dịp Tết?\n- GV chốt: chủ đề 5 giúp các em cảm nhận không khí rộn ràng của mùa xuân qua bài hát và bài đọc nhạc.","hs":"- HS nhắc lại: chủ đề Nhịp điệu mùa xuân, bài hát Xúc xắc xúc xẻ, bài đọc nhạc có năm nốt.\n- HS đọc thang âm năm nốt hai chiều kết hợp kí hiệu bàn tay.\n- HS trả lời: bài hát nhắc đến tục trẻ em đi chúc Tết, chúc nhà nhà may mắn.\n- HS lắng nghe và nhắc lại ý nghĩa của chủ đề."},{"ten":"3. Luyện tập","gv":"- (12 phút) GV cho cả lớp hát ôn bài Xúc xắc xúc xẻ theo nhạc đệm, nhắc HS hát rõ lời, nảy tiếng ở những tiếng ngắn và lấy hơi ở cuối mỗi câu.\n- Chỗ HS hát chênh cao độ hoặc hát vấp lời, GV đọc lại lời ca theo tiết tấu, đàn lại nốt đầu câu, hát mẫu chậm rồi cho HS hát nối câu sai với câu trước.\n- GV cho HS luyện ba kiểu gõ đệm: gõ theo phách, gõ theo nhịp và gõ theo tiết tấu lời ca; ở kiểu gõ theo tiết tấu lời ca, GV đọc chậm từng tiếng cho HS gõ khớp.\n- GV tổ chức chuỗi luyện tập: cả lớp, tổ (tổ hát - tổ gõ đệm rồi đổi vai), nhóm 4-6 HS, cuối cùng 2-3 HS xung phong hát cá nhân.\n- GV cho HS ôn nhanh bài đọc nhạc năm nốt kết hợp kí hiệu bàn tay và gõ phách.","hs":"- HS hát ôn cả bài theo nhạc đệm, hát rõ lời và lấy hơi đúng chỗ.\n- HS hát lại câu còn sai lời hoặc chênh cao độ theo mẫu của GV.\n- HS thực hiện ba kiểu gõ đệm theo phách, theo nhịp và theo tiết tấu lời ca.\n- HS luyện tập theo cả lớp, theo tổ, theo nhóm 4-6 bạn và cá nhân xung phong.\n- HS đọc lại bài đọc nhạc kết hợp kí hiệu bàn tay và gõ phách."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- (11 phút) GV chia nhóm 4-6 HS, giao nhiệm vụ nghĩ hai đến ba động tác phụ hoạ mang không khí ngày Tết; GV gợi ý: hai tay chắp trước ngực như chúc Tết, tay đưa cao lắc cổ tay như xúc xắc reo, chân bước nhún theo phách thành vòng tròn.\n- GV cho các nhóm tập 3 phút rồi lần lượt lên biểu diễn theo tốp ca, một bạn gõ thanh phách hoặc trống con đệm cho nhóm.\n- GV nêu tiêu chí nhận xét: thuộc lời, hát đúng giai điệu, hoà giọng, gõ đệm đúng phách, động tác đều và mạnh dạn tự tin.\n- GV củng cố chủ đề bằng câu hỏi: Bài hát cho em cảm nhận không khí mùa nào? Em sẽ nói lời chúc gì khi đi chúc Tết ông bà?\n- GV dặn HS về biểu diễn cho người thân xem và chuẩn bị SGK, thanh phách cho chủ đề Về miền dân ca.","hs":"- HS về nhóm bàn bạc và chọn động tác phụ hoạ phù hợp không khí ngày Tết.\n- HS tập theo nhóm rồi lên biểu diễn, có bạn gõ nhạc cụ đệm cho nhóm.\n- HS nhận xét nhóm bạn theo tiêu chí GV nêu.\n- HS trả lời: bài hát cho cảm nhận không khí mùa xuân; nói được lời chúc sức khoẻ ông bà.\n- HS ghi nhớ nhiệm vụ về nhà và đồ dùng cần chuẩn bị."}]},
{"lop":1,"mon":"Âm nhạc","tuan":23,"tiet":23,"bai":"Chủ đề 6: Về miền dân ca — Học hát: Gà gáy (Dân ca Cống Khao, lời mới: Huy Trân)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng giai điệu bài Gà gáy.\n- Bước đầu cảm nhận nét mộc mạc, vui tươi của làn điệu dân ca.\n2. Năng lực chung\n- Giao tiếp và hợp tác: hát hòa giọng cùng bạn.\n3. Phẩm chất\n- Yêu quê hương, trân trọng làn điệu dân ca của các dân tộc; yêu lao động.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát cùng tên tác giả.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh cảnh làng quê/gà gáy sáng, thanh phách, thiết bị số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS bắt chước tiếng gà gáy, giới thiệu ngắn về dân ca, dẫn vào bài Gà gáy.","hs":"- HS bắt chước tiếng gà, lắng nghe."},{"ten":"2. Khám phá — Học hát","gv":"- GV mở hát mẫu, đọc lời ca theo câu.\n- GV đàn và bắt nhịp cho HS tập hát từng câu đến hết bài.","hs":"- HS nghe mẫu, đọc lời, tập hát từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài, sửa sai, kết hợp vỗ tay theo phách.","hs":"- HS hát cả bài, vỗ tay theo phách."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cá nhân hát; dặn HS hát cho gia đình nghe.","hs":"- HS biểu diễn, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Gà gáy” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Dân ca Cống Khao, lời mới: Huy Trân”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Gà gáy” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Gà gáy” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Gà gáy”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."}]},
{"lop":1,"mon":"Âm nhạc","tuan":24,"tiet":24,"bai":"Chủ đề 6: Về miền dân ca — Ôn bài hát Gà gáy; Nghe nhạc: một làn điệu dân ca (Lí cây bông)","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu Gà gáy, kết hợp vỗ tay theo phách và vận động.\n- Lắng nghe và cảm nhận nét duyên dáng của một làn điệu dân ca; biết vận động nhẹ nhàng theo.\n2. Năng lực chung\n- Tự chủ: mạnh dạn nêu cảm nhận.\n3. Phẩm chất\n- Yêu dân ca, yêu quê hương.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên tác phẩm và tên tác giả có ghi trong phần chú thích.","dodung":"- GV: đàn phím điện tử hoặc file nhạc đệm bài Gà gáy, loa, tranh minh hoạ bản làng và cảnh sinh hoạt dân gian, thanh phách, bản ghi làn điệu dân ca tải sẵn, máy chiếu/tivi.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV bắt chước tiếng gà gáy ò ó o rồi hỏi: Tiếng kêu này có trong bài hát nào các em đã học?\n- GV bắt nhịp cho cả lớp hát bài Gà gáy kết hợp vỗ tay theo phách, nhắc HS lấy hơi sau tiếng ai ơi ở cuối mỗi câu.\n- GV cho HS hát lần hai theo tổ nối tiếp, mỗi tổ hát một câu, cả lớp hát câu cuối.\n- GV dẫn vào bài: tiết này lớp mình ôn bài Gà gáy và nghe một làn điệu dân ca của quê hương.","hs":"- HS nghe và trả lời đúng tên bài Gà gáy.\n- HS hát cả bài kết hợp vỗ tay theo phách, lấy hơi đúng chỗ cuối câu.\n- HS hát nối tiếp theo tổ, vào đúng câu của tổ mình.\n- HS lắng nghe, nhắc lại nội dung tiết học."},{"ten":"2. Khám phá — Nghe nhạc dân ca","gv":"- (11 phút) Trước khi nghe, GV nêu hai câu hỏi định hướng và ghi lên bảng: Làn điệu này nghe vui nhộn hay êm dịu, nhanh hay chậm? Em nghe thấy nhạc cụ nào cùng vang lên?\n- Lần nghe thứ nhất: GV mở bản ghi làn điệu dân ca Lí cây bông, HS ngồi ngay ngắn nghe trọn vẹn, không nói chuyện.\n- Lần nghe thứ hai: GV cho HS nghe kết hợp vận động nhẹ nhàng, đưa người sang trái sang phải hoặc vỗ tay khẽ theo nhịp.\n- Sau khi nghe, GV hỏi lại hai câu định hướng; dự kiến HS trả lời: làn điệu nghe duyên dáng, êm dịu, tốc độ vừa phải; nghe thấy tiếng đàn và tiếng gõ.\n- GV giới thiệu thêm: dân ca là những bài hát do nhân dân sáng tác và truyền lại qua nhiều đời, mỗi vùng miền có làn điệu riêng.","hs":"- HS đọc và ghi nhớ hai câu hỏi định hướng trước khi nghe.\n- HS ngồi ngay ngắn nghe trọn làn điệu lần thứ nhất.\n- HS nghe lần hai kết hợp vận động nhẹ nhàng hoặc vỗ tay khẽ theo nhịp.\n- HS trả lời: làn điệu êm dịu, duyên dáng, tốc độ vừa phải; nghe thấy tiếng đàn và tiếng gõ.\n- HS lắng nghe và nhắc lại được dân ca là bài hát do nhân dân truyền lại."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV cho HS ôn hát bài Gà gáy theo nhạc đệm; chỗ HS hát chênh cao độ, GV đàn lại nốt đầu câu, hát mẫu chậm rồi cho HS hát nối câu sai với câu trước.\n- GV hướng dẫn hát kết hợp gõ đệm theo phách, sau đó chuyển sang gõ theo tiết tấu lời ca để HS so sánh hai cách.\n- GV gợi ý hai động tác phụ hoạ: hai tay đưa lên miệng làm loa khi hát tiếng gà gáy, hai tay đưa cao rồi mở rộng như đón nắng sớm ở câu nắng sáng lên rồi.\n- GV luyện theo chuỗi: cả lớp, tổ, nhóm 4-6 HS rồi cá nhân xung phong; sau đó mở lại làn điệu dân ca cho HS vận động nhẹ nhàng theo.","hs":"- HS ôn hát cả bài theo nhạc đệm, sửa lại câu còn chênh cao độ.\n- HS hát kết hợp gõ đệm theo phách rồi gõ theo tiết tấu lời ca.\n- HS thực hiện hai động tác phụ hoạ theo hướng dẫn của GV.\n- HS luyện tập theo cả lớp, tổ, nhóm và cá nhân; vận động nhẹ nhàng theo làn điệu dân ca."},{"ten":"4. Vận dụng","gv":"- (6 phút) GV mời 2-3 nhóm 4-6 HS lên biểu diễn bài Gà gáy kết hợp vỗ tay theo phách và vận động phụ hoạ.\n- GV nêu tiêu chí nhận xét: thuộc lời, hát đúng giai điệu, hoà giọng, gõ đệm đúng phách, mạnh dạn tự tin.\n- GV củng cố: Hôm nay các em được nghe làn điệu dân ca nào? Bài Gà gáy là dân ca của dân tộc nào?\n- GV dặn HS về hát cho ông bà, bố mẹ nghe, hỏi người thân một bài dân ca của quê mình và mang thanh phách cho tiết học sau.","hs":"- HS lên biểu diễn theo nhóm, kết hợp vỗ tay theo phách và vận động.\n- HS nhận xét nhóm bạn theo tiêu chí GV nêu.\n- HS trả lời: được nghe làn điệu Lí cây bông; bài Gà gáy là dân ca Cống Khao.\n- HS ghi nhớ nhiệm vụ về nhà và đồ dùng cần chuẩn bị."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản ghi hình buổi biểu diễn tác phẩm “một làn điệu dân ca” (Lí cây bông) để HS vừa nghe vừa nhìn thấy người nghệ sĩ đang chơi nhạc cụ nào, ngồi và cầm đàn ra sao; GV tạm dừng đúng lúc để HS chỉ lên màn hình gọi tên nhạc cụ vừa vang lên.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV cho HS đọc phần chú thích dưới đoạn phim: tên tác phẩm, tên tác giả, tên người biểu diễn; HS hiểu bản nhạc nào cũng do một người viết ra, nhắc đến bản nhạc thì phải gọi đúng tên người ấy.\n⚠ (Miền 4: An toàn) GV chọn và tải sẵn đoạn phim về “một làn điệu dân ca” trước giờ học rồi mở ngoại tuyến để HS không nhìn thấy quảng cáo và các đoạn phim gợi ý bên cạnh; âm lượng để vừa nghe, HS ngồi cách màn hình vừa tầm mắt và không tự thao tác thiết bị.","hs":"- HS nghe và xem bản ghi hình “một làn điệu dân ca”, gọi được tên nhạc cụ đang vang lên trên màn hình.\n- HS nói được tên tác phẩm và tên tác giả có ghi trong phần chú thích."}]},
{"lop":1,"mon":"Âm nhạc","tuan":25,"tiet":25,"bai":"Chủ đề 6: Về miền dân ca — Nhạc cụ: Ôn gõ đệm; Trò chơi tiết tấu dân gian","yccd":"1. Năng lực âm nhạc\n- Gõ đệm cho bài Gà gáy bằng nhạc cụ gõ theo phách, theo tiết tấu.\n- Tham gia trò chơi gõ tiết tấu đối đáp theo nhóm.\n2. Năng lực chung\n- Giao tiếp và hợp tác: phối hợp nhóm khi chơi tiết tấu.\n3. Phẩm chất\n- Chăm chỉ luyện tập, đoàn kết.","dodung":"- GV: nhạc cụ gõ gồm thanh phách, trống con, song loan; đàn phím điện tử hoặc file nhạc đệm bài Gà gáy, loa, bảng phụ chép mẫu tiết tấu, máy chiếu/tivi.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS chơi Nghe tiết tấu đoán tên bài hát: GV gõ tiết tấu lời ca câu mở đầu của hai bài đã học, mỗi mẫu gõ hai lần, HS giơ tay đoán.\n- GV mời HS đoán đúng lên gõ lại mẫu tiết tấu đó cho cả lớp nghe và cùng gõ theo.\n- GV hỏi: Vì sao chỉ nghe tiếng gõ mà em đoán được bài hát? Tiếng gõ khớp với điều gì trong bài?\n- GV dẫn vào bài: tiết này lớp mình ôn cách gõ đệm và chơi trò chơi tiết tấu dân gian.","hs":"- HS nghe tiết tấu và giơ tay đoán đúng tên bài hát.\n- HS lên gõ lại mẫu tiết tấu, cả lớp gõ theo cho đều.\n- HS trả lời: vì tiếng gõ khớp với từng tiếng trong lời bài hát.\n- HS lắng nghe, nhắc lại nội dung tiết học."},{"ten":"2. Khám phá — Ôn nhạc cụ gõ","gv":"- (8 phút) GV đưa lần lượt thanh phách, trống con, song loan cho HS gọi tên; GV gõ từng nhạc cụ để HS nghe và so sánh: thanh phách tiếng khô gọn, trống con tiếng vang ấm, song loan tiếng đanh và sắc.\n- GV mời mỗi tổ một HS lên nhắc lại cách cầm và gõ một nhạc cụ; cả lớp quan sát và nhận xét bạn cầm đúng hay chưa.\n- GV nhắc lại lỗi hay mắc: cầm quá chặt làm tiếng bị đục, gõ quá mạnh làm tiếng chát, gõ lệch mặt nhạc cụ làm tiếng nhỏ; GV làm mẫu lại cho HS sửa.\n- GV treo bảng phụ hai mẫu tiết tấu đơn giản và gõ mẫu từng mẫu, HS gõ lại theo.","hs":"- HS gọi đúng tên ba nhạc cụ gõ và nói được đặc điểm âm thanh của mỗi loại.\n- HS lên làm mẫu cách cầm và gõ nhạc cụ, cả lớp nhận xét.\n- HS nhận ra lỗi cầm và gõ của mình, sửa lại theo mẫu của GV.\n- HS nhìn bảng phụ, nghe mẫu và gõ lại hai mẫu tiết tấu."},{"ten":"3. Luyện tập — Gõ đệm","gv":"- (12 phút) GV cho cả lớp gõ đệm cho bài Gà gáy theo phách: GV hát chậm và gõ mẫu trước, HS gõ theo, sau đó ghép với nhạc đệm.\n- GV chuyển sang gõ theo tiết tấu lời ca: GV đọc chậm từng tiếng của câu hát, HS gõ khớp mỗi tiếng một cái, sau đó ghép cả bài.\n- GV chia ba nhóm nhạc cụ: nhóm thanh phách gõ theo tiết tấu lời ca, nhóm trống con gõ theo phách, nhóm song loan gõ theo nhịp; cả ba nhóm cùng đệm cho lớp hát.\n- GV sửa sai: nhóm nào gõ nhanh dần thì GV đếm to giữ nhịp, nhóm nào gõ lấn tiếng hát thì GV nhắc gõ nhẹ tay lại.\n- GV cho luyện theo chuỗi cả lớp, tổ, nhóm 4-6 HS rồi cá nhân xung phong gõ đệm cho cả lớp hát.","hs":"- HS gõ đệm cho bài Gà gáy theo phách, ghép được với nhạc đệm.\n- HS gõ theo tiết tấu lời ca, mỗi tiếng hát một tiếng gõ.\n- HS thực hiện đúng phần gõ của nhóm nhạc cụ mình, phối hợp cùng hai nhóm còn lại.\n- HS chỉnh lại tốc độ và lực gõ theo nhắc nhở của GV.\n- HS luyện tập theo cả lớp, tổ, nhóm và cá nhân xung phong."},{"ten":"4. Vận dụng — Trò chơi tiết tấu","gv":"- (11 phút) GV chia lớp thành hai nhóm chơi Gõ tiết tấu đối đáp: nhóm 1 gõ một mẫu bốn tiếng, nhóm 2 nghe và gõ lại thật giống, sau đó đổi vai; mỗi lượt gõ đúng được một ngôi sao trên bảng.\n- GV nâng độ khó: mẫu tiết tấu có xen tiếng ngân dài và tiếng ngắn, hoặc gõ mẫu bằng hai nhạc cụ khác nhau.\n- GV tổ chức trò Vòng tròn tiết tấu: cả lớp đứng vòng tròn, GV gõ một tiếng truyền cho bạn đầu tiên, mỗi bạn lần lượt gõ một tiếng đúng phách cho vòng gõ chạy đều quanh lớp.\n- GV nêu tiêu chí tuyên dương: nghe kĩ, gõ lại đúng mẫu, gõ đều tay, phối hợp tốt với nhóm và giữ trật tự khi bạn gõ.\n- GV dặn HS giữ gìn nhạc cụ, về nhà tập gõ đệm cho bài Gà gáy và chuẩn bị đồ dùng cho tiết ôn tập chủ đề 6.","hs":"- HS chơi gõ tiết tấu đối đáp theo nhóm, nghe kĩ rồi gõ lại đúng mẫu của nhóm bạn.\n- HS gõ được mẫu tiết tấu có tiếng dài, tiếng ngắn xen kẽ.\n- HS đứng vòng tròn, gõ đúng lượt của mình cho vòng gõ chạy đều.\n- HS lắng nghe tiêu chí và tự nhận xét phần chơi của nhóm mình.\n- HS ghi nhớ việc luyện tập ở nhà và giữ gìn nhạc cụ."}]},
{"lop":1,"mon":"Âm nhạc","tuan":26,"tiet":26,"bai":"Chủ đề 6: Về miền dân ca — Vận dụng — Sáng tạo; Ôn tập chủ đề 6","yccd":"1. Năng lực âm nhạc\n- Hát thuộc và biểu diễn bài Gà gáy kết hợp vận động, gõ đệm.\n- Bước đầu sáng tạo động tác phụ họa mang màu sắc dân gian.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: nghĩ động tác, cách gõ mới.\n3. Phẩm chất\n- Yêu dân ca, tự tin thể hiện.","dodung":"- GV: đàn phím điện tử hoặc file nhạc đệm bài Gà gáy, loa, thanh phách, trống con, song loan, tranh cảnh bản làng, máy chiếu/tivi để mở học liệu số.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV bắt nhịp cho cả lớp hát bài Gà gáy kết hợp vỗ tay theo phách để tạo không khí; GV nhắc HS lấy hơi sau tiếng cuối mỗi câu, hát rõ lời.\n- GV cho hát lần hai theo hiệu lệnh tay: tay giơ cao thì hát to, tay hạ thấp thì hát thầm nhưng vẫn giữ đúng nhịp.\n- GV hỏi: Bài hát tả buổi nào trong ngày? Tiếng gà gáy báo cho mọi người biết điều gì?\n- GV dẫn vào bài: tiết này lớp mình ôn tập chủ đề Về miền dân ca và sáng tạo cách biểu diễn.","hs":"- HS hát cả bài kết hợp vỗ tay theo phách, lấy hơi đúng chỗ và hát rõ lời.\n- HS hát to hoặc hát thầm theo hiệu lệnh tay của GV, vẫn giữ đúng nhịp.\n- HS trả lời: bài hát tả buổi sáng sớm; tiếng gà gáy báo trời sáng, gọi mọi người dậy đi làm.\n- HS lắng nghe, nhắc lại nội dung tiết học."},{"ten":"2. Khám phá","gv":"- (7 phút) GV cùng HS nhắc lại chủ đề 6 qua ba câu hỏi: Chủ đề 6 có tên là gì? Các em học bài hát nào, bài đó là dân ca của dân tộc nào? Đã ôn những nhạc cụ gõ nào?\n- GV cho HS nghe lại một đoạn ngắn của làn điệu dân ca đã học ở tiết trước và hỏi cảm nhận: nghe êm dịu hay rộn ràng.\n- GV giải thích ngắn gọn: dân ca là bài hát do nhân dân sáng tác và truyền lại qua nhiều đời, hát dân ca cần mềm mại, tình cảm, không hát cứng như đọc.\n- GV làm mẫu một câu hát theo hai cách, một cách hát cứng và một cách hát mềm mại, cho HS nghe và chọn cách hay hơn.","hs":"- HS nhắc lại: chủ đề Về miền dân ca, bài Gà gáy là dân ca Cống Khao, đã ôn thanh phách, trống con, song loan.\n- HS nghe lại đoạn dân ca và nêu cảm nhận của mình.\n- HS lắng nghe và nhắc lại đặc điểm của bài dân ca.\n- HS so sánh hai cách hát mẫu và chọn cách hát mềm mại, tình cảm."},{"ten":"3. Luyện tập","gv":"- (12 phút) GV cho cả lớp hát ôn bài Gà gáy theo nhạc đệm; chỗ HS hát chênh cao độ ở những tiếng ngân cao, GV đàn lại nốt đầu câu, hát mẫu chậm rồi cho HS hát nối câu sai với câu đứng trước.\n- GV cho HS luyện ba kiểu gõ đệm: gõ theo phách, gõ theo nhịp và gõ theo tiết tấu lời ca, mỗi kiểu thực hiện một lượt cả bài.\n- GV tổ chức chuỗi luyện tập: cả lớp hát, tổ (tổ hát - tổ gõ đệm rồi đổi vai), nhóm 4-6 HS, cuối cùng 2-3 HS xung phong hát cá nhân.\n- GV cho HS chơi trò hát nối tiếp theo tổ: mỗi tổ hát một câu, cả lớp hát câu cuối, ai vào sai câu thì cả lớp hát lại từ đầu.\n- GV nhắc HS hát mềm mại, ngân đủ ở tiếng cuối câu và nhấn nhẹ ở tiếng đầu mỗi câu.","hs":"- HS hát ôn cả bài theo nhạc đệm, sửa lại những tiếng còn chênh cao độ.\n- HS thực hiện đủ ba kiểu gõ đệm theo phách, theo nhịp và theo tiết tấu lời ca.\n- HS luyện tập theo cả lớp, theo tổ, theo nhóm 4-6 bạn và cá nhân xung phong.\n- HS hát nối tiếp theo tổ, vào đúng câu của tổ mình.\n- HS hát mềm mại, ngân đủ tiếng cuối câu theo hướng dẫn."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- (12 phút) GV chia nhóm 4-6 HS, giao nhiệm vụ nghĩ hai đến ba động tác phụ hoạ mang màu sắc dân gian; GV gợi ý: hai tay đưa lên miệng làm loa khi hát tiếng gà gáy, tay che ngang trán như nhìn về phía nương xa, chân bước nhún đều theo phách.\n- GV gợi ý thêm cách gõ mới: một bạn gõ song loan giữ nhịp, các bạn còn lại gõ thanh phách theo tiết tấu lời ca.\n- GV cho các nhóm tập 3 phút rồi lần lượt lên biểu diễn theo tốp ca; cả lớp vỗ tay theo phách cổ vũ.\n- GV nêu tiêu chí nhận xét: thuộc lời, hát đúng giai điệu, hoà giọng, gõ đệm đúng phách, động tác đều và mạnh dạn tự tin.\n- GV củng cố và dặn HS ôn lại hai bài hát Xúc xắc xúc xẻ, Gà gáy cùng bài đọc nhạc năm nốt để chuẩn bị cho tiết ôn tập giữa học kì II.","hs":"- HS về nhóm bàn bạc và chọn động tác phụ hoạ mang màu sắc dân gian.\n- HS thử cách gõ đệm mới, phân công bạn giữ nhịp và bạn gõ tiết tấu.\n- HS tập theo nhóm rồi lên biểu diễn, cả lớp vỗ tay cổ vũ.\n- HS nhận xét nhóm bạn theo tiêu chí GV nêu.\n- HS ghi nhớ nhiệm vụ ôn tập ở nhà chuẩn bị cho tiết ôn tập giữa học kì."}]},
{"lop":1,"mon":"Âm nhạc","tuan":27,"tiet":27,"bai":"Ôn tập giữa học kì II — Ôn các bài hát và nội dung chủ đề 5, 6","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu các bài Xúc xắc xúc xẻ, Gà gáy.\n- Củng cố kĩ năng gõ đệm, vận động và đọc nhạc 5 nốt.\n2. Năng lực chung\n- Tự chủ và tự học: tự đánh giá kết quả học tập.\n3. Phẩm chất\n- Chăm chỉ, tự tin biểu diễn.","dodung":"- GV: đàn phím điện tử hoặc file nhạc đệm, loa, thanh phách, trống con, thăm ghi tên bài hát và hình thức biểu diễn, tranh kí hiệu bàn tay năm nốt, máy chiếu/tivi.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS chơi Nghe giai điệu đoán tên bài hát: GV đàn câu mở đầu bài Xúc xắc xúc xẻ và bài Gà gáy, mỗi câu một lần, HS giơ tay đoán.\n- GV nâng độ khó bằng cách chỉ gõ tiết tấu lời ca của một câu hát, HS nghe tiết tấu và đoán tên bài.\n- GV cho cả lớp hát lại một bài kết hợp vỗ tay theo phách để vào không khí ôn tập.\n- GV nêu nhiệm vụ tiết học: ôn lại hai bài hát, cách gõ đệm, vận động và bài đọc nhạc năm nốt.","hs":"- HS lắng nghe giai điệu, giơ tay và đoán đúng tên hai bài hát.\n- HS nghe tiết tấu gõ và đoán được câu hát tương ứng.\n- HS hát lại một bài kết hợp vỗ tay theo phách.\n- HS lắng nghe, nhắc lại nhiệm vụ của tiết ôn tập."},{"ten":"2. Khám phá — Hệ thống lại","gv":"- (7 phút) GV cùng HS hệ thống theo hai chủ đề: chủ đề 5 Nhịp điệu mùa xuân có bài Xúc xắc xúc xẻ và bài đọc nhạc Những người bạn của Đô - Rê - Mi; chủ đề 6 Về miền dân ca có bài Gà gáy và phần ôn nhạc cụ gõ.\n- GV hỏi nhanh: Bài Gà gáy là dân ca của dân tộc nào? Bài đọc nhạc gồm mấy nốt, kể tên theo thứ tự từ thấp đến cao.\n- GV cho HS làm lại kí hiệu bàn tay năm nốt và đọc thang âm đi lên Đô - Rê - Mi - Pha - Son, đi xuống Son - Pha - Mi - Rê - Đô.\n- GV thông báo trước hình thức ôn tập và các tiêu chí nhận xét để HS chuẩn bị.","hs":"- HS nhắc lại tên hai chủ đề, tên bài hát và bài đọc nhạc của mỗi chủ đề.\n- HS trả lời: bài Gà gáy là dân ca Cống Khao; bài đọc nhạc có năm nốt Đô, Rê, Mi, Pha, Son.\n- HS làm kí hiệu bàn tay và đọc thang âm năm nốt hai chiều.\n- HS lắng nghe và ghi nhớ các tiêu chí nhận xét."},{"ten":"3. Luyện tập","gv":"- (13 phút) GV cho HS ôn lần lượt từng bài: bài Xúc xắc xúc xẻ hát kết hợp gõ theo tiết tấu lời ca, bài Gà gáy hát kết hợp gõ theo phách và vận động nhẹ nhàng.\n- GV sửa từng lỗi cụ thể: hát vấp lời thì GV đọc lại lời ca theo tiết tấu; hát chênh cao độ thì GV đàn lại nốt đầu câu, hát mẫu chậm rồi cho HS hát nối câu sai với câu trước.\n- GV cho HS ôn bài đọc nhạc năm nốt: đọc theo kí hiệu bàn tay, đọc kết hợp gõ phách, đọc theo tổ nối tiếp mỗi tổ một câu.\n- GV tổ chức chuỗi luyện tập cả lớp, tổ, nhóm 4-6 HS rồi cá nhân xung phong cho từng nội dung.\n- GV lưu ý HS giữ đều nhịp khi gõ đệm, không gõ nhanh dần và không gõ to lấn tiếng hát.","hs":"- HS ôn từng bài hát kết hợp gõ đệm và vận động theo hướng dẫn.\n- HS sửa lại lời và cao độ những câu còn sai theo mẫu của GV.\n- HS đọc bài đọc nhạc năm nốt theo kí hiệu bàn tay, kết hợp gõ phách và đọc nối tiếp theo tổ.\n- HS luyện tập theo cả lớp, tổ, nhóm và cá nhân.\n- HS giữ đều nhịp gõ, gõ nhẹ hơn tiếng hát."},{"ten":"4. Vận dụng","gv":"- (11 phút) GV cho các nhóm 4-6 HS bốc thăm bài biểu diễn, trong thăm ghi tên bài hát và hình thức trình bày (hát kết hợp gõ đệm, hát kết hợp vận động, hoặc đọc bài đọc nhạc kết hợp kí hiệu bàn tay).\n- GV cho các nhóm chuẩn bị 2 phút, nhắc HS phân công bạn hát chính, bạn gõ đệm và đứng thành hàng ngay ngắn.\n- GV nêu rõ tiêu chí nhận xét: thuộc lời, hát đúng giai điệu, hoà giọng cùng nhóm, gõ đệm đúng phách, mạnh dạn tự tin.\n- Các nhóm lần lượt biểu diễn; GV nhận xét theo hướng động viên, khen cụ thể mỗi nhóm một điểm mạnh và gợi ý một điều cần luyện thêm.\n- GV dặn HS ôn lại các bài đã học và chuẩn bị SGK, thanh phách cho chủ đề Gia đình.","hs":"- HS bốc thăm theo nhóm và nhận nhiệm vụ biểu diễn.\n- HS chuẩn bị trong nhóm, phân công bạn hát chính và bạn gõ đệm.\n- HS ghi nhớ các tiêu chí trước khi lên biểu diễn.\n- HS biểu diễn trước lớp, tự nhận xét nhóm mình và nhận xét nhóm bạn.\n- HS ghi nhớ nhiệm vụ ôn tập ở nhà và đồ dùng cần chuẩn bị."}]},
{"lop":1,"mon":"Âm nhạc","tuan":28,"tiet":28,"bai":"Chủ đề 7: Gia đình — Học hát: Cây gia đình (Nhạc: Quỳnh Hợp, lời thơ: Nguyễn Thị Mai)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng giai điệu bài Cây gia đình.\n- Cảm nhận tình cảm ấm áp, gắn bó giữa các thành viên trong gia đình qua bài hát.\n2. Năng lực chung\n- Giao tiếp và hợp tác: hát hòa giọng cùng bạn.\n3. Phẩm chất\n- Yêu gia đình, kính trọng ông bà, cha mẹ.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát cùng tên tác giả.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh gia đình, thanh phách, thiết bị số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem tranh gia đình, hỏi trong nhà em có những ai, dẫn vào bài.","hs":"- HS quan sát, chia sẻ."},{"ten":"2. Khám phá — Học hát","gv":"- GV mở hát mẫu, đọc lời ca theo câu.\n- GV đàn và bắt nhịp cho HS tập hát từng câu đến hết bài.","hs":"- HS nghe mẫu, đọc lời, tập hát từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài, sửa sai, kết hợp vỗ tay theo phách.","hs":"- HS hát cả bài, vỗ tay theo phách."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cá nhân hát; dặn HS hát cho ông bà, bố mẹ nghe.","hs":"- HS biểu diễn, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Cây gia đình” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Nhạc: Quỳnh Hợp, lời thơ: Nguyễn Thị Mai”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Cây gia đình” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Cây gia đình” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Cây gia đình”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."}]},
{"lop":1,"mon":"Âm nhạc","tuan":29,"tiet":29,"bai":"Chủ đề 7: Gia đình — Ôn bài hát Cây gia đình; Nghe nhạc: Con chim vành khuyên (Hoàng Vân)","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu Cây gia đình, kết hợp vận động phụ họa.\n- Lắng nghe và cảm nhận giai điệu vui tươi, trong sáng của bài Con chim vành khuyên; biết vận động nhẹ nhàng theo nhạc.\n2. Năng lực chung\n- Tự chủ: mạnh dạn nêu cảm nhận.\n3. Phẩm chất\n- Yêu gia đình, biết ơn ông bà cha mẹ.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên tác phẩm và tên tác giả có ghi trong phần chú thích.","dodung":"- GV: đàn phím điện tử hoặc file nhạc đệm bài Cây gia đình, loa, tranh ảnh gia đình, thanh phách, bản ghi bài Con chim vành khuyên tải sẵn, máy chiếu/tivi.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV cho HS xem tranh một gia đình và hỏi: Trong tranh có những ai? Gia đình em có mấy người?\n- GV bắt nhịp cho cả lớp hát bài Cây gia đình kết hợp vỗ tay theo phách, nhắc HS lấy hơi ở cuối mỗi câu hát.\n- GV cho hát lần hai theo hình thức nối tiếp: tổ 1 hát câu 1, tổ 2 hát câu 2, cả lớp hát câu cuối.\n- GV dẫn vào bài: tiết này lớp mình ôn bài hát và nghe thêm một bài hát rất quen thuộc.","hs":"- HS quan sát tranh và trả lời về các thành viên trong gia đình.\n- HS hát cả bài kết hợp vỗ tay theo phách, lấy hơi đúng chỗ.\n- HS hát nối tiếp theo tổ, vào đúng câu của tổ mình.\n- HS lắng nghe, nhắc lại nội dung tiết học."},{"ten":"2. Khám phá — Nghe nhạc","gv":"- (11 phút) Trước khi nghe, GV nêu hai câu hỏi định hướng và ghi lên bảng: Bài hát vui tươi hay êm dịu, nhanh hay chậm? Bài hát nói về con vật nào và con vật ấy làm gì?\n- Lần nghe thứ nhất: GV mở bản ghi bài Con chim vành khuyên, HS ngồi ngay ngắn nghe trọn vẹn, không nói chuyện.\n- Lần nghe thứ hai: GV cho HS nghe kết hợp vỗ tay khẽ theo nhịp hoặc đưa người nhẹ nhàng theo nhạc.\n- Sau khi nghe, GV hỏi lại hai câu định hướng; dự kiến HS trả lời: bài hát vui tươi, trong sáng, nhịp vừa phải; bài hát nói về chú chim vành khuyên ngoan ngoãn biết chào hỏi mọi người.\n- GV chốt: bài hát của nhạc sĩ Hoàng Vân mượn hình ảnh chú chim để nhắc các em biết lễ phép chào hỏi ông bà, cha mẹ.","hs":"- HS đọc và ghi nhớ hai câu hỏi định hướng trước khi nghe.\n- HS ngồi ngay ngắn nghe trọn bài lần thứ nhất.\n- HS nghe lần hai kết hợp vỗ tay khẽ theo nhịp hoặc đưa người nhẹ nhàng.\n- HS trả lời: bài hát vui tươi, trong sáng; nói về chú chim vành khuyên biết chào hỏi.\n- HS lắng nghe và nhắc lại tên tác phẩm cùng tên tác giả."},{"ten":"3. Luyện tập","gv":"- (10 phút) GV cho HS ôn hát bài Cây gia đình theo nhạc đệm; chỗ HS hát chênh cao độ, GV đàn lại nốt đầu câu, hát mẫu chậm rồi cho HS hát nối câu sai với câu trước.\n- GV hướng dẫn ba động tác phụ hoạ: hát về ông bà thì hai tay chắp trước ngực cúi nhẹ, hát về bố mẹ thì hai tay đưa ra phía trước như ôm, câu cuối hai tay đặt lên ngực rồi mở rộng.\n- GV cho HS luyện theo chuỗi: cả lớp cùng làm, tổ 1 hát tổ 2 vận động rồi đổi vai, nhóm 4-6 HS, cuối cùng cá nhân xung phong.\n- GV mở lại bài nghe nhạc một lần nữa cho HS đứng vận động nhẹ nhàng và cảm thụ.","hs":"- HS ôn hát cả bài theo nhạc đệm, sửa lại câu còn chênh cao độ.\n- HS thực hiện ba động tác phụ hoạ theo hướng dẫn của GV.\n- HS luyện tập theo cả lớp, theo tổ, theo nhóm 4-6 bạn và cá nhân.\n- HS đứng vận động nhẹ nhàng, cảm thụ bài nghe nhạc."},{"ten":"4. Vận dụng","gv":"- (6 phút) GV mời 2-3 nhóm 4-6 HS lên biểu diễn bài Cây gia đình kết hợp vận động phụ hoạ, khuyến khích HS xung phong hát cá nhân.\n- GV nêu tiêu chí nhận xét: thuộc lời, hát đúng giai điệu, hoà giọng, động tác đều và mạnh dạn tự tin.\n- GV củng cố: Hôm nay các em được nghe bài hát nào, của nhạc sĩ nào? Em sẽ làm gì để ông bà, cha mẹ vui lòng?\n- GV dặn HS về hát bài Cây gia đình cho cả nhà nghe và mang thanh phách cho tiết học nhạc cụ tuần sau.","hs":"- HS lên biểu diễn theo nhóm, một số bạn xung phong hát cá nhân.\n- HS nhận xét bạn theo tiêu chí GV nêu.\n- HS trả lời: bài Con chim vành khuyên của nhạc sĩ Hoàng Vân; sẽ chào hỏi lễ phép, giúp việc nhà.\n- HS ghi nhớ nhiệm vụ về nhà và đồ dùng cần chuẩn bị."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản ghi hình buổi biểu diễn tác phẩm “Con chim vành khuyên” (Hoàng Vân) để HS vừa nghe vừa nhìn thấy người nghệ sĩ đang chơi nhạc cụ nào, ngồi và cầm đàn ra sao; GV tạm dừng đúng lúc để HS chỉ lên màn hình gọi tên nhạc cụ vừa vang lên.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV cho HS đọc phần chú thích dưới đoạn phim: tên tác phẩm, tên tác giả, tên người biểu diễn; HS hiểu bản nhạc nào cũng do một người viết ra, nhắc đến bản nhạc thì phải gọi đúng tên người ấy.\n⚠ (Miền 4: An toàn) GV chọn và tải sẵn đoạn phim về “Con chim vành khuyên” trước giờ học rồi mở ngoại tuyến để HS không nhìn thấy quảng cáo và các đoạn phim gợi ý bên cạnh; âm lượng để vừa nghe, HS ngồi cách màn hình vừa tầm mắt và không tự thao tác thiết bị.","hs":"- HS nghe và xem bản ghi hình “Con chim vành khuyên”, gọi được tên nhạc cụ đang vang lên trên màn hình.\n- HS nói được tên tác phẩm và tên tác giả có ghi trong phần chú thích."}]},
{"lop":1,"mon":"Âm nhạc","tuan":30,"tiet":30,"bai":"Chủ đề 7: Gia đình — Nhạc cụ: Gõ đệm theo bài hát; Vận động theo cặp","yccd":"1. Năng lực âm nhạc\n- Gõ đệm cho bài Cây gia đình bằng nhạc cụ gõ theo phách.\n- Biết hát kết hợp vận động phụ họa theo cặp/nhóm.\n2. Năng lực chung\n- Giao tiếp và hợp tác: phối hợp gõ đệm, biểu diễn cùng bạn.\n3. Phẩm chất\n- Yêu gia đình, đoàn kết, chăm chỉ.","dodung":"- GV: thanh phách, trống con, song loan; đàn phím điện tử hoặc file nhạc đệm bài Cây gia đình, loa, tranh ảnh gia đình, máy chiếu/tivi để mở học liệu số.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV bắt nhịp cho cả lớp hát bài Cây gia đình kết hợp vỗ tay theo phách, nhắc HS hát rõ lời và lấy hơi ở cuối mỗi câu.\n- GV cho hát lần hai theo hiệu lệnh tay: tay giơ cao thì hát to, tay hạ thấp thì hát thầm, giúp HS tập giữ nhịp trong đầu.\n- GV hỏi: Bài hát ví mỗi người trong gia đình với bộ phận nào của cây? Vì sao lại ví như vậy?\n- GV dẫn vào bài: tiết này lớp mình tập gõ đệm cho bài hát và vận động theo cặp.","hs":"- HS hát cả bài kết hợp vỗ tay theo phách, hát rõ lời và lấy hơi đúng chỗ.\n- HS hát to hoặc hát thầm theo hiệu lệnh tay, vẫn giữ đúng nhịp.\n- HS trả lời theo cảm nhận: mỗi người là một cành, một lá của cây gia đình.\n- HS lắng nghe, nhắc lại nội dung tiết học."},{"ten":"2. Khám phá — Ôn cách gõ đệm","gv":"- (9 phút) GV nhắc lại tư thế cầm nhạc cụ: thanh phách cầm lỏng tay để thanh còn rung, trống con đặt trên bàn và cầm dùi ở giữa cán, cổ tay mềm, gõ xong nhấc dùi lên ngay.\n- GV hát bài Cây gia đình thật chậm và gõ mẫu theo phách để HS nghe rõ tiếng gõ rơi vào tiếng hát nào; GV làm mẫu hai lần.\n- GV làm mẫu tiếp cách gõ theo nhịp, chỉ gõ vào phách mạnh của mỗi nhịp, và cho HS so sánh với cách gõ theo phách.\n- GV nêu lỗi HS hay mắc và cách sửa: gõ nhanh dần thì GV đếm to giữ nhịp; gõ quá mạnh lấn tiếng hát thì nhắc gõ nhẹ tay; gõ lệch phách thì GV gõ cùng vài nhịp rồi buông ra.","hs":"- HS nhắc lại và thực hiện đúng tư thế cầm thanh phách, cầm dùi trống con.\n- HS nghe mẫu và nhận ra tiếng hát nào cần gõ vào.\n- HS gõ thử theo phách rồi theo nhịp, so sánh được hai cách gõ.\n- HS nhận ra lỗi của mình và sửa lại theo hướng dẫn của GV."},{"ten":"3. Luyện tập — Gõ đệm","gv":"- (12 phút) GV cho cả lớp vừa hát vừa gõ đệm theo phách cho bài Cây gia đình, thực hiện hai lượt: lượt một hát chậm không nhạc đệm, lượt hai ghép với nhạc đệm.\n- GV chuyển sang gõ theo tiết tấu lời ca: GV đọc chậm từng tiếng của câu hát, HS gõ khớp mỗi tiếng một cái rồi ghép cả bài.\n- GV hướng dẫn vận động theo cặp: hai bạn quay mặt vào nhau, câu 1 vỗ tay mình hai cái rồi vỗ tay bạn một cái, câu 2 nắm tay nhau đung đưa theo phách, câu cuối cùng giơ tay lên cao.\n- GV cho HS luyện theo chuỗi: cả lớp, tổ (tổ hát - tổ gõ đệm rồi đổi vai), theo cặp, nhóm 4-6 HS và cá nhân xung phong.\n- GV quan sát, sửa cho từng cặp còn vỗ lệch nhịp bằng cách đếm to 1-2 cho cặp đó bắt lại.","hs":"- HS vừa hát vừa gõ đệm theo phách, ghép được với nhạc đệm.\n- HS gõ theo tiết tấu lời ca, mỗi tiếng hát một tiếng gõ.\n- HS thực hiện vận động theo cặp, vỗ tay mình và vỗ tay bạn đúng nhịp.\n- HS luyện tập theo cả lớp, theo tổ, theo cặp, theo nhóm và cá nhân.\n- HS bắt lại đúng nhịp theo tiếng đếm của GV khi bị lệch."},{"ten":"4. Vận dụng","gv":"- (10 phút) GV cho các nhóm 4-6 HS luân phiên lên biểu diễn: một nửa nhóm hát và vận động theo cặp, một nửa nhóm gõ đệm bằng thanh phách và trống con.\n- GV khuyến khích các nhóm tự chọn nhạc cụ và chọn kiểu gõ đệm phù hợp, giải thích ngắn vì sao nhóm chọn kiểu gõ đó.\n- GV nêu tiêu chí nhận xét: hát thuộc lời và đúng giai điệu, gõ đệm đúng phách, phối hợp nhịp nhàng với bạn cùng cặp, cầm nhạc cụ đúng cách, mạnh dạn tự tin.\n- GV củng cố: Hôm nay các em đã gõ đệm cho bài hát bằng những cách nào? Vận động theo cặp cần chú ý điều gì?\n- GV dặn HS giữ gìn nhạc cụ, về nhà tập hát và vận động cùng người thân, chuẩn bị đồ dùng cho tiết ôn tập chủ đề 7.","hs":"- HS lên biểu diễn theo nhóm, phân công bạn hát, bạn vận động và bạn gõ đệm.\n- HS chọn nhạc cụ, chọn kiểu gõ đệm cho nhóm và nói được lí do chọn.\n- HS nhận xét nhóm bạn theo tiêu chí GV nêu.\n- HS trả lời: gõ theo phách, theo nhịp và theo tiết tấu lời ca; vận động theo cặp cần nhìn bạn để vỗ cho khớp.\n- HS ghi nhớ nhiệm vụ về nhà và đồ dùng cần chuẩn bị."}]},
{"lop":1,"mon":"Âm nhạc","tuan":31,"tiet":31,"bai":"Chủ đề 7: Gia đình — Vận dụng — Sáng tạo; Ôn tập chủ đề 7","yccd":"1. Năng lực âm nhạc\n- Hát thuộc và biểu diễn bài Cây gia đình kết hợp vận động, gõ đệm.\n- Củng cố cảm nhận tình cảm gia đình qua âm nhạc.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: nghĩ động tác phụ họa.\n3. Phẩm chất\n- Yêu gia đình, tự tin thể hiện.","dodung":"- GV: đàn phím điện tử hoặc file nhạc đệm bài Cây gia đình, loa, thanh phách, trống con, tranh ảnh gia đình, máy chiếu/tivi để mở học liệu số.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (5 phút) GV cho HS chơi trò Đoán người thân bằng động tác: GV làm động tác vuốt râu là ông, bế em là mẹ, cuốc đất là bố; HS quan sát và đoán đó là ai trong gia đình.\n- GV mời lần lượt vài HS lên nghĩ một động tác về người thân của mình, cả lớp cùng đoán.\n- GV hỏi: Trong nhà em, ai là người hay hát cho em nghe? Em thường hát bài gì cho người thân nghe?\n- GV dẫn vào bài: tiết này lớp mình ôn tập chủ đề Gia đình và sáng tạo động tác biểu diễn.","hs":"- HS quan sát động tác của GV và đoán đúng người thân được nhắc đến.\n- HS lên nghĩ và làm động tác về người thân cho cả lớp đoán.\n- HS trả lời theo trải nghiệm của mình về người thân và bài hát mình hay hát.\n- HS lắng nghe, nhắc lại nội dung tiết học."},{"ten":"2. Khám phá","gv":"- (7 phút) GV cùng HS nhắc lại chủ đề 7 qua ba câu hỏi: Chủ đề 7 có tên là gì? Các em học bài hát nào? Đã nghe bài hát nào và của nhạc sĩ nào?\n- GV cho HS nhắc lại các cách gõ đệm đã học ở tiết trước và gõ thử mỗi cách bốn nhịp để kiểm tra tay.\n- GV hỏi về cảm xúc: Khi hát bài Cây gia đình, em thấy trong lòng vui hay xúc động? Nên hát bài này với giọng thế nào cho hợp?\n- GV chốt: bài hát cần hát với giọng ấm áp, tình cảm, không hát quá to hay quá nhanh.","hs":"- HS nhắc lại: chủ đề Gia đình, bài hát Cây gia đình, bài nghe nhạc Con chim vành khuyên của nhạc sĩ Hoàng Vân.\n- HS gõ thử các cách gõ đệm đã học, mỗi cách bốn nhịp.\n- HS nói được cảm xúc của mình khi hát và chọn giọng hát phù hợp.\n- HS lắng nghe và nhắc lại cách hát bài với giọng ấm áp, tình cảm."},{"ten":"3. Luyện tập","gv":"- (12 phút) GV cho cả lớp hát ôn bài Cây gia đình theo nhạc đệm, nhắc HS hát rõ lời, lấy hơi ở cuối mỗi câu và giữ giọng ấm áp.\n- Chỗ HS hát chênh cao độ, GV đàn lại nốt đầu của câu đó, hát mẫu chậm hai lần rồi cho HS hát nối câu sai với câu đứng trước cho liền mạch.\n- GV cho HS luyện ba kiểu gõ đệm: gõ theo phách, gõ theo nhịp và gõ theo tiết tấu lời ca, mỗi kiểu một lượt cả bài.\n- GV tổ chức chuỗi luyện tập: cả lớp hát, tổ (tổ hát - tổ gõ đệm rồi đổi vai), theo cặp, nhóm 4-6 HS, cuối cùng cá nhân xung phong.\n- GV cho HS chơi trò hát to - hát thầm theo hiệu lệnh tay để rèn giữ nhịp trong đầu.","hs":"- HS hát ôn cả bài theo nhạc đệm, hát rõ lời với giọng ấm áp.\n- HS hát lại câu còn chênh cao độ theo mẫu chậm của GV.\n- HS thực hiện ba kiểu gõ đệm theo phách, theo nhịp và theo tiết tấu lời ca.\n- HS luyện tập theo cả lớp, theo tổ, theo cặp, theo nhóm 4-6 bạn và cá nhân.\n- HS chơi hát to - hát thầm, vẫn giữ đúng nhịp khi hát thầm."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- (11 phút) GV chia nhóm 4-6 HS, giao nhiệm vụ nghĩ hai đến ba động tác phụ hoạ cho bài hát; GV gợi ý: hai tay chắp lại đặt bên má như đang ngủ ngoan, hai tay đưa lên cao xoè ra như tán cây, các bạn nắm tay nhau thành vòng tròn ở câu cuối.\n- GV cho các nhóm tập 3 phút rồi lần lượt lên biểu diễn theo tốp ca, một bạn gõ thanh phách hoặc trống con đệm cho nhóm.\n- GV nêu tiêu chí nhận xét: thuộc lời, hát đúng giai điệu, hoà giọng, gõ đệm đúng phách, động tác đều và mạnh dạn tự tin.\n- GV củng cố chủ đề: Bài hát muốn nhắn nhủ các em điều gì về gia đình? Em sẽ làm việc gì để giúp ông bà, cha mẹ?\n- GV dặn HS về biểu diễn cho cả nhà xem và chuẩn bị SGK, thanh phách cho chủ đề Vui đón hè.","hs":"- HS về nhóm bàn bạc và chọn động tác phụ hoạ phù hợp với lời bài hát.\n- HS tập theo nhóm rồi lên biểu diễn, có bạn gõ nhạc cụ đệm cho nhóm.\n- HS nhận xét nhóm bạn theo tiêu chí GV nêu.\n- HS trả lời: bài hát nhắc phải yêu thương gia đình; sẽ quét nhà, trông em giúp bố mẹ.\n- HS ghi nhớ nhiệm vụ về nhà và đồ dùng cần chuẩn bị."}]},
{"lop":1,"mon":"Âm nhạc","tuan":32,"tiet":32,"bai":"Chủ đề 8: Vui đón hè — Học hát: Ngôi sao lấp lánh (Nhạc nước ngoài; sưu tầm, biên soạn: Thanh Vân)","yccd":"1. Năng lực âm nhạc\n- Nhớ tên và hát rõ lời, đúng giai điệu bài Ngôi sao lấp lánh.\n- Cảm nhận tính chất nhẹ nhàng, trong sáng của bài hát.\n2. Năng lực chung\n- Giao tiếp và hợp tác: hát hòa giọng cùng bạn.\n3. Phẩm chất\n- Yêu thiên nhiên, yêu bầu trời đêm mùa hè.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS nói được tên bài hát cùng tên tác giả.","dodung":"- Giáo viên: đàn/file nhạc, loa, tranh bầu trời sao mùa hè, thanh phách, thiết bị số.\n- Học sinh: SGK Âm nhạc 1, thanh phách.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem tranh bầu trời đêm đầy sao, hỏi các em thấy gì, dẫn vào bài.","hs":"- HS quan sát, trả lời."},{"ten":"2. Khám phá — Học hát","gv":"- GV mở hát mẫu, đọc lời ca theo câu.\n- GV đàn và bắt nhịp cho HS tập hát từng câu đến hết bài.","hs":"- HS nghe mẫu, đọc lời, tập hát từng câu."},{"ten":"3. Luyện tập","gv":"- GV cho HS hát cả bài, sửa sai, kết hợp vỗ tay theo phách.","hs":"- HS hát cả bài, vỗ tay theo phách."},{"ten":"4. Vận dụng","gv":"- GV mời nhóm/cá nhân hát; dặn HS hát cho gia đình nghe.","hs":"- HS biểu diễn, ghi nhớ nhiệm vụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV mở bản thu mẫu bài “Ngôi sao lấp lánh” lấy từ học liệu điện tử của bộ sách hoặc kênh chính thức của nhà xuất bản, phóng màn hình để cả lớp nhìn thấy tên bài hát, chỉ cho HS dòng ghi tác giả “Nhạc nước ngoài; sưu tầm, biên soạn: Thanh Vân”; GV mở từng câu, tạm dừng cho HS nghe kĩ rồi hát theo, câu nào HS hát chênh cao độ thì GV mở lại đúng câu đó.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV dùng điện thoại thu âm phần hát bài “Ngôi sao lấp lánh” của cả lớp rồi mở lại ngay cho HS nghe; HS chỉ ra chỗ mình hát to quá, nhỏ quá hoặc sai lời — nghe lại giọng của chính mình là điều hát chay không có được. GV thao tác thiết bị, HS nghe và nhận xét.\n⚠ (Miền 4: An toàn) Bản thu bài “Ngôi sao lấp lánh” chỉ lấy từ học liệu của bộ sách hoặc kênh chính thức, không tải nhạc từ trang lạ vì có thể sai lời, sai nhạc và kèm quảng cáo không phù hợp; giới thiệu bài hát phải nói rõ tên tác giả; mở loa vừa đủ nghe, không để loa sát tai HS.","hs":"- HS nghe bản thu mẫu và hát đúng lời, đúng cao độ bài “Ngôi sao lấp lánh”.\n- HS nói được tên bài hát cùng tên tác giả; nghe lại bản thu của lớp và chỉ ra một chỗ cần sửa."}]},
{"lop":1,"mon":"Âm nhạc","tuan":33,"tiet":33,"bai":"Chủ đề 8: Vui đón hè — Ôn bài hát Ngôi sao lấp lánh; Nhạc cụ: Trai-en-gô (Triangle)","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu Ngôi sao lấp lánh, thể hiện sắc thái to — nhỏ.\n- Nhận biết, gọi tên nhạc cụ trai-en-gô; biết cách gõ và gõ đệm theo bài hát.\n2. Năng lực chung\n- Tự chủ và tự học: tự luyện tập gõ đệm.\n3. Phẩm chất\n- Chăm chỉ luyện tập nhạc cụ.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS cầm và gõ được nhạc cụ Trai-en-gô đúng cách sau khi xem phim cận cảnh.","dodung":"- GV: nhạc cụ trai-en-gô cùng dùi gõ (hoặc vật thay thế phát tiếng trong trẻo), đàn phím điện tử hoặc file nhạc đệm bài Ngôi sao lấp lánh, loa, tranh nhạc cụ, máy chiếu/tivi.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV bắt nhịp cho cả lớp hát bài Ngôi sao lấp lánh kết hợp vỗ tay theo phách, nhắc HS lấy hơi ở cuối mỗi câu hát.\n- GV cho hát lần hai thể hiện sắc thái: hai câu đầu hát vừa phải, câu tả ngôi sao sáng thì hát to hơn, câu cuối hát nhỏ dần như ngôi sao xa dần.\n- GV hỏi: Bài hát tả cảnh vào lúc nào trong ngày? Ngôi sao trên trời trông như thế nào?\n- GV dẫn vào bài: hôm nay lớp mình làm quen một nhạc cụ có tiếng ngân trong trẻo như ánh sao, đó là trai-en-gô.","hs":"- HS hát cả bài kết hợp vỗ tay theo phách, lấy hơi đúng chỗ.\n- HS hát lần hai thể hiện được sắc thái to dần rồi nhỏ dần theo hướng dẫn.\n- HS trả lời: bài hát tả cảnh ban đêm, ngôi sao nhỏ và lấp lánh.\n- HS lắng nghe, nhắc lại tên nhạc cụ sắp học."},{"ten":"2. Khám phá — Giới thiệu trai-en-gô","gv":"- (9 phút) GV đưa trai-en-gô cho HS quan sát: thanh kim loại uốn thành hình tam giác, có một cạnh hở, kèm một dùi kim loại nhỏ; tiếng phát ra trong trẻo và ngân dài hơn thanh phách.\n- GV làm mẫu tư thế: tay trái cầm sợi dây treo nhạc cụ, để nhạc cụ buông tự do trong không khí, không chạm vào lòng bàn tay; tay phải cầm dùi gõ nhẹ vào cạnh đáy rồi nhấc ra ngay cho tiếng ngân.\n- GV gõ mẫu chậm hai lần, cho HS nghe tiếng ngân dài; sau đó GV nắm tay vào nhạc cụ để tiếng tắt ngay, giúp HS so sánh hai cách.\n- GV nêu lỗi HS hay mắc và cách sửa: cầm chặt vào thân nhạc cụ làm tiếng cụt thì hướng dẫn cầm dây treo; gõ quá mạnh làm tiếng chát thì gõ nhẹ tay; gõ liên tục không để tiếng ngân hết thì nhắc chờ tiếng ngân rồi mới gõ tiếp.","hs":"- HS quan sát và nói được: nhạc cụ hình tam giác bằng kim loại, tiếng trong trẻo, ngân dài.\n- HS cầm dây treo và gõ thử theo đúng mẫu của GV.\n- HS nghe và so sánh được tiếng ngân dài với tiếng bị tắt khi nắm vào nhạc cụ.\n- HS nhận ra lỗi cầm và gõ của mình, sửa lại theo hướng dẫn."},{"ten":"3. Luyện tập — Gõ đệm","gv":"- (10 phút) GV cho HS gõ trai-en-gô theo tiếng đếm 1-2 khoảng một phút, yêu cầu gõ nhẹ, để tiếng ngân hết rồi mới gõ tiếng tiếp theo.\n- GV hát bài Ngôi sao lấp lánh thật chậm và gõ mẫu theo nhịp, chỉ gõ vào phách mạnh đầu mỗi nhịp cho tiếng ngân không chồng lên nhau.\n- GV cho HS vừa hát vừa gõ đệm theo nhịp cả bài, sau đó thử gõ theo phách để HS thấy gõ dày quá thì tiếng bị lẫn.\n- GV chia hai nhóm nhạc cụ: nhóm thanh phách gõ theo tiết tấu lời ca, nhóm trai-en-gô gõ theo nhịp; hai nhóm cùng đệm cho lớp hát và đổi vai sau mỗi lượt.","hs":"- HS gõ trai-en-gô theo tiếng đếm, chờ tiếng ngân hết rồi mới gõ tiếp.\n- HS nghe mẫu và nhận ra tiếng hát nào cần gõ vào.\n- HS vừa hát vừa gõ đệm theo nhịp, so sánh với cách gõ theo phách.\n- HS thực hiện đúng phần gõ của nhóm mình và đổi vai với nhóm bạn."},{"ten":"4. Vận dụng","gv":"- (8 phút) GV cho các nhóm 4-6 HS luân phiên lên biểu diễn: một số bạn hát, một bạn gõ trai-en-gô theo nhịp, một bạn gõ thanh phách theo tiết tấu lời ca.\n- GV khuyến khích HS thể hiện sắc thái to - nhỏ khi hát và gõ nhẹ dần ở câu cuối cho hợp với hình ảnh ngôi sao xa dần.\n- GV nêu tiêu chí nhận xét: cầm và gõ trai-en-gô đúng cách, gõ đúng nhịp, hát thuộc lời và hoà giọng, thể hiện được sắc thái, mạnh dạn tự tin.\n- GV dặn HS giữ gìn nhạc cụ, về nhà tập hát bài Ngôi sao lấp lánh cho người thân nghe và chuẩn bị đồ dùng cho tiết đọc nhạc cuối chủ đề.","hs":"- HS lên biểu diễn theo nhóm, phân công bạn hát và bạn gõ từng loại nhạc cụ.\n- HS thể hiện sắc thái to - nhỏ khi hát và gõ nhẹ dần ở câu cuối.\n- HS nhận xét nhóm bạn theo tiêu chí GV nêu.\n- HS ghi nhớ việc luyện tập ở nhà và giữ gìn nhạc cụ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV chiếu đoạn phim quay cận cảnh nhạc cụ Trai-en-gô: nhìn rõ hình dáng, chất liệu, cách cầm và cách gõ sao cho ra đúng tiếng; GV tua chậm đúng động tác khó, cho xem lại hai ba lần rồi mới phát nhạc cụ thật để HS làm theo.\n- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV thu âm tiếng gõ Trai-en-gô của từng tổ rồi mở lại cho cả lớp nghe; HS nghe ra tổ nào gõ đều, tổ nào còn lúc nhanh lúc chậm — nghe lại bản thu giúp HS nhận ra điều mà lúc đang gõ không nhận ra được.\n⚠ (Miền 4: An toàn) Cầm Trai-en-gô đúng cách, gõ vừa lực, không đập mạnh xuống bàn và không chĩa vào người bạn; GV thao tác máy chiếu và điện thoại, HS không tự cầm thiết bị; bản thu tiếng gõ của lớp chỉ mở trong giờ học, không gửi ra ngoài lớp.","hs":"- HS cầm và gõ được nhạc cụ Trai-en-gô đúng cách sau khi xem phim cận cảnh.\n- HS nghe lại bản thu tiếng gõ của tổ và chỉ ra chỗ gõ chưa đều."}]},
{"lop":1,"mon":"Âm nhạc","tuan":34,"tiet":34,"bai":"Chủ đề 8: Vui đón hè — Đọc nhạc: Hát cùng Đô — Rê — Mi — Pha — Son; Vận dụng — Sáng tạo","yccd":"1. Năng lực âm nhạc\n- Đọc đúng cao độ 5 nốt Đô — Rê — Mi — Pha — Son theo kí hiệu bàn tay, thể hiện sắc thái to — nhỏ.\n- Biểu diễn bài Ngôi sao lấp lánh kết hợp vận động, gõ đệm.\n2. Năng lực chung\n- Giải quyết vấn đề và sáng tạo: nghĩ động tác phụ họa.\n3. Phẩm chất\n- Yêu âm nhạc, tự tin thể hiện.\n4. Tích hợp\n- Năng lực số 1.1 CB1b: Tìm được cách truy cập những dữ liệu, thông tin và nội dung này cũng như điều hướng giữa chúng: HS đọc đúng cao độ “Hát cùng Đô — Rê — Mi — Pha — Son” nhờ nghe mẫu từ đàn phím.","dodung":"- GV: đàn phím điện tử, loa, tranh kí hiệu bàn tay năm nốt, bảng phụ chép bài đọc nhạc, thanh phách, trai-en-gô, trống con, máy chiếu/tivi.\n- HS: SGK Âm nhạc 1, thanh phách hoặc nhạc cụ gõ tự tạo.","hoatdong":[{"ten":"1. Khởi động","gv":"- (4 phút) GV đàn năm nốt Đô - Rê - Mi - Pha - Son rồi làm kí hiệu bàn tay, cả lớp đọc theo thang âm đi lên và đi xuống, mỗi chiều hai lần.\n- GV chơi trò đố nhanh: GV làm một kí hiệu bàn tay bất kì, HS đọc ngay tên nốt và đọc đúng cao độ; GV làm nhanh dần để tạo hứng thú.\n- GV hỏi: Trong năm nốt vừa đọc, nốt nào cao nhất, nốt nào thấp nhất?\n- GV dẫn vào bài đọc nhạc Hát cùng Đô - Rê - Mi - Pha - Son.","hs":"- HS đọc thang âm năm nốt đi lên, đi xuống theo tay GV.\n- HS nhìn kí hiệu bàn tay và đọc ngay tên nốt, đọc đúng cao độ.\n- HS trả lời: nốt Son cao nhất, nốt Đô thấp nhất.\n- HS lắng nghe, nhắc lại tên bài đọc nhạc."},{"ten":"2. Khám phá — Đọc nhạc","gv":"- (10 phút) GV treo bảng phụ bài đọc nhạc, chỉ cho HS thấy bài gồm bốn câu ngắn; GV chỉ từng nốt cho HS gọi tên nốt trước khi đọc cao độ.\n- GV đàn lấy cao độ chuẩn rồi đọc mẫu cả bài một lần, thể hiện rõ sắc thái: câu đi lên đọc to dần, câu đi xuống đọc nhỏ dần.\n- GV dạy theo lối móc xích: đọc mẫu câu 1 hai lần rồi bắt nhịp cho HS đọc lại, làm tương tự câu 2 rồi ghép hai câu; dạy tiếp câu 3, câu 4 rồi ghép cả bài.\n- GV sửa sai: chỗ HS đọc chênh cao độ, GV đàn lại nốt đầu câu đó, đọc mẫu thật chậm rồi cho HS đọc nối câu sai với câu đứng trước.","hs":"- HS quan sát bảng phụ, đếm được bốn câu và gọi đúng tên các nốt.\n- HS nghe GV đọc mẫu, nhận ra chỗ đọc to dần và chỗ đọc nhỏ dần.\n- HS đọc từng câu theo lối móc xích, ghép hai câu rồi ghép cả bài.\n- HS đọc lại câu còn chênh cao độ theo mẫu chậm của GV."},{"ten":"3. Luyện tập","gv":"- (11 phút) GV cho cả lớp đọc cả bài hai lần: lần một kết hợp kí hiệu bàn tay, lần hai kết hợp gõ phách bằng thanh phách, nhắc HS gõ đều tay và nhẹ hơn tiếng đọc.\n- GV luyện theo chuỗi: cả lớp đọc, tổ 1 đọc tổ 2 gõ phách rồi đổi vai, nhóm 4-6 HS, cuối cùng cá nhân xung phong đọc trước lớp.\n- GV chuyển sang ôn hát bài Ngôi sao lấp lánh theo nhạc đệm, nhắc HS thể hiện sắc thái to - nhỏ và lấy hơi ở cuối mỗi câu.\n- GV hướng dẫn vận động: hai tay giơ cao xoè các ngón rồi khép lại như ngôi sao nhấp nháy, chân nhún nhẹ theo phách, câu cuối hạ tay xuống chậm.\n- GV cho HS luyện hát kết hợp vận động và gõ đệm theo tổ rồi theo nhóm.","hs":"- HS đọc cả bài kết hợp kí hiệu bàn tay, sau đó đọc kết hợp gõ phách đều tay.\n- HS luyện đọc theo cả lớp, theo tổ, theo nhóm 4-6 bạn và cá nhân xung phong.\n- HS ôn hát bài Ngôi sao lấp lánh, thể hiện sắc thái to - nhỏ và lấy hơi đúng chỗ.\n- HS thực hiện động tác tay nhấp nháy như ngôi sao, chân nhún nhẹ theo phách.\n- HS luyện hát kết hợp vận động và gõ đệm theo tổ, theo nhóm."},{"ten":"4. Vận dụng — Sáng tạo","gv":"- (5 phút) GV chia nhóm 4-6 HS, giao nhiệm vụ chọn thêm một động tác phụ hoạ của riêng nhóm và chọn một nhạc cụ gõ để đệm cho bài hát.\n- GV mời các nhóm lần lượt lên biểu diễn; khuyến khích một vài HS xung phong đọc lại bài đọc nhạc kết hợp kí hiệu bàn tay.\n- GV nêu tiêu chí nhận xét: đọc đúng cao độ năm nốt, hát thuộc lời và đúng giai điệu, hoà giọng, gõ đệm đúng phách, động tác đều và mạnh dạn tự tin.\n- GV củng cố chủ đề: Chủ đề 8 có tên là gì? Các em đã học bài hát nào, bài đọc nhạc nào và nhạc cụ nào?\n- GV dặn HS ôn lại các bài hát, bài đọc nhạc đã học cả năm để chuẩn bị cho tiết ôn tập, đánh giá cuối năm học.","hs":"- HS về nhóm chọn động tác phụ hoạ riêng và chọn nhạc cụ gõ để đệm.\n- HS lên biểu diễn theo nhóm, một số bạn xung phong đọc lại bài đọc nhạc.\n- HS nhận xét nhóm bạn theo tiêu chí GV nêu.\n- HS trả lời: chủ đề Vui đón hè, bài Ngôi sao lấp lánh, bài đọc nhạc năm nốt, nhạc cụ trai-en-gô.\n- HS ghi nhớ nhiệm vụ ôn tập ở nhà chuẩn bị cho tiết cuối năm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 1: Khai thác dữ liệu và thông tin — Cơ bản, bậc 1) GV dùng đàn phím điện tử hoặc phần mềm đàn phím trên máy tính để lấy cao độ chuẩn cho “Hát cùng Đô — Rê — Mi — Pha — Son”: bấm từng nốt cho HS nghe rõ, bấm chậm cả câu, rồi bấm lại đúng nốt mà HS còn đọc chênh — cao độ lấy từ đàn chuẩn hơn lấy từ giọng người vì không bị lệch theo hơi thở.\n- (Miền 5: Giải quyết vấn đề — Cơ bản, bậc 1) GV mở trò chơi nghe nốt trên máy: máy phát một nốt, HS giơ kí hiệu bàn tay tương ứng, GV bấm lại nốt đó để cả lớp cùng kiểm tra ngay đúng hay sai rồi đọc lại — HS biết mình sai ở nốt nào ngay tại chỗ chứ không chờ hết giờ.\n⚠ (Miền 4: An toàn) GV thao tác đàn và máy tính, HS chỉ nghe và đọc theo, không tự bấm vào thiết bị của GV; mở âm lượng vừa đủ nghe để không hại tai; chỉ dùng phần mềm GV đã cài sẵn, không mở phần mềm hay trang khác trong giờ học.","hs":"- HS đọc đúng cao độ “Hát cùng Đô — Rê — Mi — Pha — Son” nhờ nghe mẫu từ đàn phím.\n- HS nhận ra ngay nốt mình đọc còn chênh và đọc lại cho đúng."}]},
{"lop":1,"mon":"Âm nhạc","tuan":35,"tiet":35,"bai":"Ôn tập và đánh giá cuối năm học","yccd":"1. Năng lực âm nhạc\n- Hát thuộc, đúng giai điệu các bài hát đã học trong năm; biết gõ đệm và vận động phù hợp.\n- Nhận biết các nhạc cụ gõ đã học (thanh phách, trống con, trai-en-gô) và đọc được 5 nốt Đô-Rê-Mi-Pha-Son.\n2. Năng lực chung\n- Tự chủ và tự học: tự đánh giá kết quả học tập cả năm.\n3. Phẩm chất\n- Chăm chỉ, tự tin biểu diễn.\n4. Tích hợp\n- Năng lực số 3.3 CB1a: Xác định được các quy tắc đơn giản về bản quyền và giấy phép áp dụng cho dữ liệu, thông tin và nội dung số: HS trả lời đúng bộ câu hỏi ôn tập và gọi được tên bài hát, tên tác giả đã học.","dodung":"- Giáo viên: đàn/file nhạc, loa, nhạc cụ gõ, phiếu đánh giá, thiết bị số.\n- Học sinh: thanh phách, SGK Âm nhạc 1.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS chơi Nghe giai điệu đoán tên bài hát đã học trong năm.","hs":"- HS lắng nghe, đoán tên bài."},{"ten":"2. Khám phá — Hệ thống","gv":"- GV cùng HS hệ thống lại các bài hát, nhạc cụ, nội dung đọc nhạc đã học cả năm.","hs":"- HS nhắc lại kiến thức."},{"ten":"3. Luyện tập — Đánh giá","gv":"- GV cho từng nhóm/cá nhân biểu diễn một bài tự chọn; GV nhận xét, đánh giá theo sự tiến bộ.","hs":"- HS biểu diễn, tự nhận xét và nhận xét bạn."},{"ten":"4. Vận dụng","gv":"- GV tổ chức buổi biểu diễn nhỏ tổng kết năm học; tuyên dương, động viên HS; dặn dò HS giữ tình yêu âm nhạc trong dịp hè.","hs":"- HS tham gia biểu diễn, cổ vũ bạn, ghi nhớ."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Miền 3: Sáng tạo nội dung số — Cơ bản, bậc 1) GV quay lại phần biểu diễn cuối năm học của từng tổ rồi mở lên màn hình cho cả lớp xem; HS chỉ ra chỗ tổ mình hát đều, chỗ vào chưa cùng lúc và nói mình sẽ sửa thế nào nếu được hát lại.\n- (Miền 6: Ứng dụng trí tuệ nhân tạo — Cơ bản, bậc 1) GV mở cho HS nghe hai đoạn nhạc ngắn cùng một giai điệu: một đoạn do nghệ sĩ hát, một đoạn do máy tự tạo ra. HS đoán đoạn nào do người hát và nói vì sao mình nghĩ vậy; GV giải thích máy làm theo những bản nhạc nó đã học nên hát rất đều nhưng chưa có hơi thở và tình cảm của người hát. GV thao tác hoàn toàn, HS chỉ nghe và trả lời.\n⚠ (Miền 4: An toàn) Đoạn phim quay lớp chỉ mở trong giờ học và trong buổi họp phụ huynh khi cả lớp đồng ý, không đăng lên mạng, không gửi cho người ngoài; bạn nào không muốn bị quay thì GV không quay; nhận xét bạn bằng lời tử tế, không chê bai hình dáng hay giọng hát của bạn.","hs":"- HS xem lại đoạn phim phần biểu diễn của tổ và chỉ ra được một chỗ cần sửa.\n- HS trả lời đúng bộ câu hỏi ôn tập và gọi được tên bài hát, tên tác giả đã học."}]}
];
